/* ===== 通用书源的正文段评注入 =====
   任何书源只要在正文响应里给出 review_list / god_list / title_review 与 cmtBase，
   就能用下面这套渲染，不需要为它在书源里新加分支。
   起点与番茄各自保留原有实现（它们的取数方式不同，且是线上主力，不动）。 */

/* 从章节 URL 上取书源标识。'' 表示起点（老书源不带 source 参数即起点）。 */
function srcKeyOf(u) {
    var m = String(u || '').match(/[?&]source=([A-Za-z0-9_]+)/);
    return m ? m[1] : '';
}

/* cmtBase 可能是相对路径（由后台 *_absolute_url 开关决定），补成绝对地址 */
function srcAbs(u) {
    u = String(u || '');
    if (!u) return '';
    return /^https?:\/\//.test(u) ? u : (qdWebBase.call(this) + u);
}

/* 段评气泡。list 为 [{paragraphId(显示行号,1基), paraIndex(源内标识), textCount}]。
   paraIndex 可能是不透明字符串（书旗是 p000 这类），所以一律按字符串处理、绝不转数字。 */
/* 剥掉正文里已注入的气泡/神评 <img>，只留纯文字。
   段评弹窗顶部的「引用」用的就是这段文字：不剥的话，凡是已经挂过气泡的段落，
   引用区会把一整串 data:image/svg+xml;base64,... 原样显示出来。
   神评尤其明显——它在段评注入**之后**执行，拿到的行必然已经带着气泡 img。 */
function srcPlainLine(s) {
    return String(s || '').replace(/<img\s[^>]*>/gi, '').replace(/\s+$/, '');
}

function srcGetComments(content, list, cmtBase) {
    var java = this.java, cache = this.cache, self = this;
    try {
        if (!list || !list.length) return content;
        var separator = '\n';
        if (/<p>/.test(content)) { content = content.replace('<p>', '').replace('\n', ''); separator = '<p>'; }
        else { content = content.replace(/\r/g, '').replace(/\n$/, ''); }
        var comcont = content.split(separator);
        /* 用一次性 token 把本章的 cmtBase 与各段原文存进内存缓存：
           点击回调里只拿得到 SVG 里编码的参数，不可能再拿到 cmtBase。 */
        var tok = 'k' + Date.now();
        cache.putMemory('srccmt-' + tok + '-base', String(cmtBase || ''));
        for (var k = 0; k < list.length; k++) {
            var x = list[k], idx = Number(x.paragraphId) - 1;
            var pIndex = (typeof x.paraIndex !== 'undefined' && x.paraIndex !== null) ? String(x.paraIndex) : String(x.paragraphId);
            if (idx >= 0 && idx < comcont.length && comcont[idx]) {
                cache.putMemory('srccmt-' + tok + '-' + pIndex + '-text', srcPlainLine(comcont[idx]));
                var svg = createSvg.call({ source: self.source, java: java, cache: cache }, x.textCount, tok, pIndex, 0);
                svg = svg.split('"androidshowCmt(').join('"srcAndroidShowCmt(').split('"showCmt(').join('"srcShowCmt(');
                /* createSvg 是按数字参数拼的，这里把 token 与不透明段号补上引号 */
                svg = svg.split('(' + tok + ', ' + pIndex + ', 0, ').join("('" + tok + "','" + pIndex + "', 0, ");
                comcont[idx] += '<img src="' + svg + '">';
            }
        }
        return comcont.join('\n');
    } catch (e) { java.log('srcGetComments: ' + e); return content; }
}

/* 正文内嵌神评。数据已随正文一起下发，不再额外请求。 */
function srcGetGods(content, gods, cmtBase) {
    var java = this.java, cache = this.cache, self = this;
    try {
        if (!gods || !gods.length) return content;
        var byLine = {};
        for (var i = 0; i < gods.length; i++) {
            var g = gods[i];
            if (g && g.text) byLine[String(g.paragraphId)] = g;
        }
        var tok = 'g' + Date.now();
        cache.putMemory('srccmt-' + tok + '-base', String(cmtBase || ''));
        var lines = content.split('\n'), out = [], pid = 0;
        for (var j = 0; j < lines.length; j++) {
            out.push(lines[j]);
            if (/^\s*<img\s+src="https?:/.test(lines[j])) continue;
            pid++;
            var god = byLine[String(pid)];
            if (!god) continue;
            var pIndex = String(god.paraIndex || pid);
            cache.putMemory('srccmt-' + tok + '-' + pIndex + '-text', srcPlainLine(lines[j]));
            var img = createGodSvg.call({ java: java, source: self.source, cache: cache },
                { Content: god.text }, tok, pIndex, 0);
            if (!img) continue;
            img = img.split('"androidshowCmt(').join('"srcAndroidShowCmt(').split('"showCmt(').join('"srcShowCmt(');
            img = img.split('(' + tok + ', ' + pIndex + ', 0, ').join("('" + tok + "','" + pIndex + "', 0, ");
            if (/^<span rs-native>/.test(lines[j])) { out.push('<span rs-native>' + img + '</span>'); }
            else { out.push(img); }
        }
        return out.join('\n');
    } catch (e) { java.log('srcGetGods: ' + e); return content; }
}

/* 章节标题上的评论气泡。写进 java 变量，由 ruleContent.title 读出来拼到标题后面
   （与起点的 qd_title_svg 走同一条路，因此标题规则不用改）。 */
function srcTitleBubble(tr, cmtBase, chapterTitle) {
    var java = this.java, cache = this.cache, self = this;
    try {
        java.put('qd_title_svg', '');
        if (!tr || !(tr.textCount > 0)) return;
        var pIndex = String(tr.paraIndex || '');
