        var tok = 't' + Date.now();
        cache.putMemory('srccmt-' + tok + '-base', String(cmtBase || ''));
        /* 标题评论没有"段落原文"，引用区改用章节名——上游不返回它，只能由这里带上 */
        cache.putMemory('srccmt-' + tok + '-' + pIndex + '-text', String(chapterTitle || ''));
        var svg = createSvg.call({ source: self.source, java: java, cache: cache }, tr.textCount, tok, pIndex, 0);
        svg = svg.split('"androidshowCmt(').join('"srcAndroidShowCmt(').split('"showCmt(').join('"srcShowCmt(');
        svg = svg.split('(' + tok + ', ' + pIndex + ', 0, ').join("('" + tok + "','" + pIndex + "', 0, ");
