        cache.putMemory('srccmt-' + tok + '-' + pIndex + '-full', String(say.url || (cmtBase + '&kind=chapterSay')));
        cache.putMemory('srccmt-' + tok + '-' + pIndex + '-text', '本章说');
        var img = createSayCard.call({ source: self.source, java: java, cache: cache },
            say.total, say.list || [], tok, pIndex);
        img = img.split('"androidshowCmt(').join('"srcAndroidShowCmt(').split('"showCmt(').join('"srcShowCmt(');
        img = img.split('(' + tok + ', ' + pIndex + ', 0, ').join("('" + tok + "','" + pIndex + "', 0, ");
        return img;
    } catch (e) { java.log('srcSayCard: ' + e); return ''; }
}

function srcCmtUrl(tok, pIndex) {
    var cache = this.cache;
    /* 整条 URL 覆盖：本章说这类视图不带 paragraphId，链接由服务端整条给出 */
    var full = String(cache.getFromMemory('srccmt-' + tok + '-' + pIndex + '-full') || '');
    if (full) return full + this.appSession();
    var base = String(cache.getFromMemory('srccmt-' + tok + '-base') || '');
    if (!base) return '';
