    if(!tok) return '';
    tok=tok.replace(/[^A-Za-z0-9._\-]/g,'');
    if(!tok) return '';
    try{ source.put('qd_at',tok); }catch(e){}
    try{ qdSaveLoginInfo({'访问令牌':tok}); }catch(e){}
    return tok;
}
function qdCtx(){ return {source:source, java:java, cookie:cookie, cache:(typeof cache!=='undefined'?cache:null)}; }
function qdKillToken(){
    try{ source.put('qd_tok_valid','0'); }catch(e){}
