    try{ _doms[String(source.bookSourceUrl)]=1; }catch(e){}
    for(var _d in _doms){
        try{
            var _ck=String(cookie.getCookie(_d)||'');
            if(_ck.indexOf('at=')>=0){
                var _keep=[], _parts=_ck.split(';');
                for(var _i=0;_i<_parts.length;_i++){ var _p=String(_parts[_i]).replace(/^\s+|\s+$/g,''); if(_p && _p.indexOf('at=')!==0) _keep.push(_p); }
                cookie.removeCookie(_d);
