        if (!st.data.globalEnabled) { java.longToast('后台未开启彩蛋章功能，此开关暂时无效'); return; }
        var next = st.data.enabled ? '0' : '1';
        var r = JSON.parse(java.ajax(b + '/user/api/midpage-pref/set?on=' + next));
        if (r && r.code === 0) { try { source.put('qd_midpage_cache', r.data.enabled ? '1' : '0'); } catch (e) {} java.longToast(r.data.enabled ? '彩蛋章已开启\n返回目录下拉刷新即可看到' : '彩蛋章已关闭\n返回目录下拉刷新即可移除'); try { java.reLoginView(); } catch (e) {} }
        else { java.longToast((r && r.message) || '设置失败'); }
    } catch (e) { java.longToast('设置失败（请先登录）：' + e); }
}
/* ===== 书源选项：由后端下发，新增书源时无需重新分发书源 ===== */

/* 后端拉不到时的兜底列表。
   只在离线/后端异常时用到——没有它登录页会渲染出空下拉，用户连原有的源都选不了。 */
function qdUiFallback() {
    return {
        ver: 0,
        search: [{ value: 'all', label: '全部' }, { value: 'qidian', label: '起点' }, { value: 'fanqie', label: '番茄' }],
        explore: [{ value: 'qidian', label: '起点' }, { value: 'fanqie', label: '番茄' }],
        modes: [{ value: 'all', label: '全部' }, { value: 'novel', label: '小说' }, { value: 'audio', label: '听书' }, { value: 'manga', label: '漫画' }, { value: 'drama', label: '短剧' }]
    };
}

/* 取选项数据。缓存 6 小时：登录页每次打开都拉一次会明显变慢，
   而"本站启用了哪些源"是低频变化。force=true 供「刷新书源列表」按钮强制重取。 */
/* 登录状态一变，选项里的「（无权限）」标记就该重算，所以登录成功时清掉缓存。 */
function qdUiInvalidate() {
    try { source.put('qd_ui_opts_ts', '0'); } catch (e) {}
}

function qdUiOptions(force) {
    var raw = '', ts = 0;
    try {
        raw = String(source.get('qd_ui_opts') || '');
        ts = parseInt(String(source.get('qd_ui_opts_ts') || '0'), 10) || 0;
    } catch (e) {}
    var fresh = raw && !force && (new Date().getTime() - ts) < 21600000;
    if (!fresh) {
        try {
            var t = java.ajax(qdApiBase.call(qdCtx()) + '/api/booksource/ui');
            var j = JSON.parse(t);
            if (j && j.code === 0 && j.search && j.search.length) {
                raw = t;
                try {
                    source.put('qd_ui_opts', raw);
                    source.put('qd_ui_opts_ts', String(new Date().getTime()));
                } catch (e) {}
            }
        } catch (e) {}
    }
    if (raw) {
        try {
            var o = JSON.parse(raw);
            if (o && o.search && o.search.length) return o;
        } catch (e) {}
    }
    return qdUiFallback();
}

function qdOptLabels(list) {
    var a = [];
    for (var i = 0; i < (list || []).length; i++) a.push(String(list[i].label));
    return a;
}
function qdOptValue(list, label) {
    for (var i = 0; i < (list || []).length; i++) {
        if (String(list[i].label) === String(label)) return String(list[i].value);
    }
    return '';
}
function qdOptLabel(list, value) {
    for (var i = 0; i < (list || []).length; i++) {
        if (String(list[i].value) === String(value)) return String(list[i].label);
    }
    return '';
}

/* 老版本书源把内容形态存成「小说模式」这类中文值，这里归一到英文 token。
   不归一的话，升级后下拉找不到对应项，会显示成第一项——用户以为自己的选择被重置了。 */
function qdNormMode(v) {
    v = String(v || '');
    var map = { '小说模式': 'novel', '听书模式': 'audio', '漫画模式': 'manga', '短剧模式': 'drama', '漫剧模式': 'motion', '短篇模式': 'short', '全部': 'all', '全部类型': 'all' };
    return map[v] || v;
}

function qdSrcCsv() {
    try { return String(source.get('fqm_enabled_cache') || ''); } catch (e) { return ''; }
}

/* 当前「搜索来源」对应哪个预设选项。返回 '' 表示是个自定义子集（如三源里只选了两个），
   由 loginUi 另加一个自定义项显示——否则下拉会停在一个与实际不符的选项上。 */
function qdSrcLabel(ui) {
    var csv = qdSrcCsv();
    if (!csv) return '';
    var arr = csv.split(',');
    var total = 0;
    for (var i = 0; i < ui.search.length; i++) { if (String(ui.search[i].value) !== 'all') total++; }
    if (total > 0 && arr.length >= total) return qdOptLabel(ui.search, 'all');
    if (arr.length === 1) return qdOptLabel(ui.search, arr[0]);
    return '';
}

/* 把 CSV 里的源 key 翻成中文名，用于自定义项的显示 */
function qdSrcCsvLabels(ui, csv) {
    var arr = String(csv || '').split(','), out = [];
    for (var i = 0; i < arr.length; i++) {
        var l = qdOptLabel(ui.search, arr[i]);
        out.push(l || arr[i]);
    }
    return out.join('+');
}

/* 保证「当前值」一定在下拉选项里。
   Legado 的 setSelectionSafely 会把找不到的下标夹成 0：下拉显示第一项，
   而实际存的仍是原值，且不会触发选中回调——用户看到的和生效的不一致，
   而且怎么点都对不上。缺失时把它补进选项列表，宁可多一项也不能显示错。 */
function qdEnsureOpt(opts, cur) {
    if (cur && opts.indexOf(cur) < 0) opts.unshift(cur);
    return opts;
}

function onSrcPick() {
    var lbl = '';
    try { lbl = String(result['搜索来源'] || ''); } catch (e) {}
    if (!lbl || lbl.indexOf('自定义') === 0) return; /* 自定义项：点回自己，不做任何事 */
    var v = qdOptValue(qdUiOptions().search, lbl);
    if (!v) { java.toast('未识别的书源：' + lbl); return; }
    setSrc(v);
}

function onExplorePick() {
    var lbl = '';
    try { lbl = String(result['发现来源'] || ''); } catch (e) {}
    if (!lbl) return;
    var v = qdOptValue(qdUiOptions().explore, lbl);
    if (!v) { java.toast('未识别的发现来源：' + lbl); return; }
    setExplore(v);
}

function onModePick() {
    var lbl = '';
    try { lbl = String(result['内容形态'] || ''); } catch (e) {}
    if (!lbl) return;
    var v = qdOptValue(qdUiOptions().modes, lbl);
    if (!v) { java.toast('未识别的内容形态：' + lbl); return; }
    setFqType(v);
}

function refreshSrcOptions() {
    var ui = qdUiOptions(true);
    java.longToast('已刷新：可选书源 ' + Math.max(0, qdOptLabels(ui.search).length - 1) + ' 个\n' + qdSrcCsvLabels(ui, qdSrcCsv()));
    try { java.reLoginView(); } catch (e) {}
}
