function normalizeHostLines(raw) {
  raw = String(raw === null || raw === undefined ? '' : raw).trim();
  return raw.split(/\r?\n/).map(function(x) { return x.trim().replace(/\/+$/, ''); })
    .filter(function(x, i, arr) { return /^https?:\/\//i.test(x) && arr.indexOf(x) === i; });
}

function saveHosts(raw, silent) {
  var list = normalizeHostLines(raw);
  if (!list.length) {
    if (!silent) java.toast('请按每行一个地址填写服务器');
    return false;
  }
  var d = readSourceConfig();
  d.hosts = list;
  d.server_id = 0;
  d.server = list[0];
  d.server_check_time = 0;
  writeSourceConfig(d);
  try { java.refreshExplore(); } catch (eExplore) {}
  if (!silent) java.toast('已保存 ' + list.length + ' 条服务器线路，发现页已按新线路重载');
  return true;
}

function setHost() {
  var list = getHostList.call(this);
  if (!list.length) { java.toast('没有可切换的服务器'); return; }
  var id = (Number(GET('server_id') || 0) + 1) % list.length;
  var target = list[id];
  var alive = false;
  try {
    var probeRoot = JSON.parse(java.ajax(buildApiUrl.call(this, '/api/health', target)));
    alive = !!(probeRoot && probeRoot.code === 0);
  } catch (eProbe) {}
  if (!alive) {
    java.toast('❌ 该线路无响应，未切换：\n' + target + '\n可用「📡 检测全部线路」查看可用性');
    return;
  }
  SET('server', target);
  SET('server_id', id);
  SET('server_check_time', Date.now());
  try { java.refreshExplore(); } catch (eExplore) {}
  java.toast('✅ 已切换至（探活通过）：\n' + target);
}

