// ==== 变量定义 ====
var defaultHost = String(source.bookSourceUrl || '').trim().replace(/\/+$/, '');
var _pyfqLocalVersion = "0.78";
if (!/^https?:\/\//i.test(defaultHost)) defaultHost = '';
var hosts = defaultHost ? [defaultHost] : [];

// loginUi 按钮运行在独立作用域，必须使用 loginUrl 顶层闭包函数。
var legacySourceConfigCacheKey = "pyfqSourceConfig";
var sourceConfigCacheKey = legacySourceConfigCacheKey + ":" + encodeURIComponent(String(source.bookSourceUrl || ''));

function defaultSourceConfig() {
  return {
    'sytjs': typeof sytjs === 'undefined' ? [] : sytjs,
    'sytj_type': '',
    'sytj_title': '',
    "频道": "男频",
    "bd_id": 2,
    "tone": "tone_id=0",
    "server_id": 0,
    "server": hosts[0] || '',
    "hosts": hosts,
    "api_key": "",
    "type": "小说模式",
    "module": 3,
    "showPara": true,
    "showChap": true,
    "showAuthor": true,
    "showBook": true,
    "showGod": true,
    "showBook": true,
    "tone_cn": "",
    "videoQuality": "high",
    "richToc": false,
    "audioSubtitle": false,
    "richIntro": true,
    "commentDefaultsVersion": 4,
    "isRandomBubble": false
  };
}

function normalizeSourceConfig(data) {
  var state = data && typeof data === 'object' && !Array.isArray(data) ? data : {};
  var defaults = defaultSourceConfig();
  for (var key in defaults) {
    if (Object.prototype.hasOwnProperty.call(defaults, key) && !Object.prototype.hasOwnProperty.call(state, key)) {
      state[key] = defaults[key];
    }
  }
  var sourceHost = String(source.bookSourceUrl || '').trim().replace(/\/+$/, '');
  if (!/^https?:\/\//i.test(sourceHost)) sourceHost = '';
  var configuredHosts = state.hosts;
  if (!Array.isArray(configuredHosts)) configuredHosts = String(configuredHosts || '').split(/\r?\n/);
  configuredHosts = configuredHosts.map(function(host) { return String(host || '').trim().replace(/\/+$/, ''); })
    .filter(function(host, index, values) { return /^https?:\/\//i.test(host) && values.indexOf(host) === index; });
  if (sourceHost && configuredHosts.indexOf(sourceHost) < 0) configuredHosts.push(sourceHost);
  var activeHost = String(state.server || '').trim().replace(/\/+$/, '');
  if (/^https?:\/\//i.test(activeHost) && configuredHosts.indexOf(activeHost) < 0) configuredHosts.push(activeHost);
  if (!/^https?:\/\//i.test(activeHost)) activeHost = configuredHosts[0] || '';
  state.hosts = configuredHosts;
  state.server = activeHost;
  state.server_id = Math.max(0, configuredHosts.indexOf(activeHost));
  return state;
}

function syncSourceSwitches(state) {
  ['showPara','showChap','showAuthor','showBook','showGod','richToc','audioSubtitle','richIntro'].forEach(function(name) {
    try { java.put(name, state[name] === true); } catch (e) {}
  });
}

// 保持沐凡原源 GET/SET 写法，避免登录面板函数影响发现页规则。
function GET(k) {
  var d = {};
  try { d = JSON.parse(source.getVariable() || '{}'); } catch (e) { d = {}; }
  return Object.prototype.hasOwnProperty.call(d, k) ? d[k] : '';
}

function SET(k, v) {
  var d = {};
  try { d = JSON.parse(source.getVariable() || '{}'); } catch (e) { d = {}; }
  d[k] = v;
  writeSourceConfig(d);
}

function readSourceConfig() {
  var fromCache = {};
  var fromVariable = {};
  try { fromCache = JSON.parse(cache.get(sourceConfigCacheKey) || '{}'); } catch (e0) { fromCache = {}; }
  try { fromVariable = JSON.parse(source.getVariable() || '{}'); } catch (e1) { fromVariable = {}; }
  if (!fromCache || typeof fromCache !== 'object') fromCache = {};
  if (!fromVariable || typeof fromVariable !== 'object') fromVariable = {};
  if (!Object.keys(fromCache).length && !Object.keys(fromVariable).length) {
    try { fromVariable = JSON.parse(cache.get(legacySourceConfigCacheKey) || '{}'); } catch (e2) { fromVariable = {}; }
  }
  var merged = {};
  var k;
  for (k in fromVariable) {
    if (Object.prototype.hasOwnProperty.call(fromVariable, k)) merged[k] = fromVariable[k];
  }
  for (k in fromCache) {
    if (Object.prototype.hasOwnProperty.call(fromCache, k)) merged[k] = fromCache[k];
  }
  return merged;
}

function writeSourceConfig(data) {
  var raw = JSON.stringify(data || {}, null, '\t');
  try { cache.put(sourceConfigCacheKey, raw); } catch (e0) {}
  try {
    source.setVariable(raw);
  } catch (e1) {
    source.putVariable(raw);
  }
  return raw;
}

function getHostList() {
  var d = {};
  try { d = JSON.parse(source.getVariable() || '{}'); } catch (e) { d = {}; }
  var list = d.hosts;
  if (!Array.isArray(list)) list = String(list || '').split(/\r?\n/);
  list = list.map(function(x) { return String(x || '').trim().replace(/\/+$/, ''); })
    .filter(function(x, i, arr) { return /^https?:\/\//i.test(x) && arr.indexOf(x) === i; });
  var sourceHost = String(source.bookSourceUrl || '').trim().replace(/\/+$/, '');
  if (/^https?:\/\//i.test(sourceHost) && list.indexOf(sourceHost) < 0) list.push(sourceHost);
  return list;
}

function buildApiUrl(path, host) {
  var base = String(host || GET('server') || source.bookSourceUrl || '').trim().replace(/\/+$/, '');
  var url = base + (String(path || '').startsWith('/') ? path : '/' + path);
  var key = GET('api_key');
  if (!key) {
    try {
      var info = source.getLoginInfoMap() || {};
      key = info['API密钥'] || (info.get ? info.get('API密钥') : '') || '';
    } catch (e) {}
  }
  if (key && !/[?&]api_key=/.test(url)) url += (url.indexOf('?') >= 0 ? '&' : '?') + 'api_key=' + encodeURIComponent(key);
  return url;
}

function autoSetHost(force) {
  var list = getHostList();
  if (!list.length) return '';
  var current = String(GET('server') || '');
  var lastCheck = Number(GET('server_check_time') || 0);
  if (!force && current && Date.now() - lastCheck < 60000) return current;
  var start = Number(GET('server_id') || 0) % list.length;
  for (var i = 0; i < list.length; i++) {
    var id = (start + i) % list.length;
    try {
      var root = JSON.parse(java.ajax(buildApiUrl('/api/health', list[id])));
      if (root && root.code === 0) {
        SET('server', list[id]); SET('server_id', id); SET('server_check_time', Date.now());
        return list[id];
      }
    } catch (e) {}
  }
  return current || list[0];
}

function API(path) {
  return buildApiUrl(path, autoSetHost(false));
}

function requestJSON(path) {
  var list = getHostList();
  var current = String(GET('server') || '');
  var start = Math.max(0, list.indexOf(current));
  var lastError = '';
  for (var i = 0; i < list.length; i++) {
    var id = (start + i) % list.length;
    try {
      var root = JSON.parse(java.ajax(buildApiUrl(path, list[id])));
      if (!root || root.code !== 0) throw new Error((root && root.msg) || '接口返回异常');
      SET('server', list[id]); SET('server_id', id); SET('server_check_time', Date.now());
      return root;
    } catch (e) { lastError = String(e); }
  }
  throw new Error(lastError || '所有服务器均不可用');
}

