<js>
//java.toast(result)
(function(result) {
let te = GET('type');
java.log(te);
// 首页推荐处理
function parseTabItem(tabItem, fg) {
  var bookList = [];
  var videoList = [];

  if (!tabItem || typeof tabItem !== 'object') return [];

  function isArray(obj) {
    return Array.isArray(obj) || Object.prototype.toString.call(obj) === '[object JavaList]';
  }

  function walk(node) {
    if (!node || typeof node !== 'object') return;

    var i, len;

    if (isArray(node.book_data) && node.book_data.length > 0) {
      for (i = 0, len = node.book_data.length; i < len; i++) {
        var b = node.book_data[i];
        if (b && typeof b === 'object') bookList.push(b);
      }
    }

    if (isArray(node.video_data) && node.video_data.length > 0) {
      for (i = 0, len = node.video_data.length; i < len; i++) {
        var v = node.video_data[i];
        if (v && typeof v === 'object') videoList.push(v);
      }
    }

    if (isArray(node.cell_data)) {
      for (i = 0, len = node.cell_data.length; i < len; i++) {
        walk(node.cell_data[i]);
      }
    }

    if (isArray(node)) {
    	java.log('node')
      for (i = 0, len = node.length; i < len; i++) {
        walk(node[i]);
      }
    }
  }

  walk(tabItem);

  if (fg) return bookList.concat(videoList);

  if (bookList.length > 0) return bookList;
  return videoList;
}
// 首页推荐处理
if (result[0] && result[0].title && !result[0].series_id) {
  java.toast('\n首页推荐处理')
  let res = '';
  //java.longToast('\n当前推荐: ' + GET('sytj_title'))
  res = parseTabItem(result, false);

  return res;
}

// 关联作品处理
if (result.length == 0) { java.toast('\n没有关联作品'); return []; }
if (('cell_name' in result[0]) && result[0].cell_name == "关联作品") {
  java.toast('\n关联作品处理')
  return parseTabItem(result[0], true);
}

// 作者书架处理
//java.toast(result[0])
if (result[0] && result[0].book) {
  java.toast('\n作者书架处理')
  let res = [];
  result.forEach(x => { res.push(x.book); });
  return res;
}

// 标签处理
if (result[0] && (result[0].abstract || result[0].series_id)) return result;

if (baseUrl.indexOf('/api/book_shelf?') >= 0) return result;

// 书架处理
if (result[0].book_id) {
let pg = baseUrl.match(/&page=(\d+)/)?.[1] || 1; // 防御：正则可能匹配失败
let url = API.call(this, '/api/detail?book_id={bookId}');
let res = [];

// 用 Math.min 限制上限，防止越界
let limit = Math.min(result.length, pg * 10);

for (let i = 0; i < limit; i++) {
let x = result[i];
// 再加一层防御，虽然 Math.min 已经保证了，但习惯上保留也不坏
if (!x || !x.book_id) continue;

let resp = java.ajax(url.replace('{bookId}', x.book_id));
resp = JSON.parse(resp);
res.push(JSON.stringify(resp.data));
}

return res;
}

// 榜单处理
return parseTabItem(result, true);
})(result);
</js>

