            fanqie_tts_tone: newFanqieTone,
            shuqi_tts_tone: newShuqiTone
        });

        function findToneName(list, id) {
            for (var i = 0; i < list.length; i++) {
                if (list[i].id == id) return list[i].name;
            }
            return id;
        }

        var msg = '';
        if (newFanqieTone) msg += '番茄: ' + findToneName(fanqieTones, newFanqieTone);
        if (newShuqiTone) msg += (msg ? ' | ' : '') + '书旗: ' + findToneName(shuqiTones, newShuqiTone);
        if (!msg) msg = '已清除音色';
        java.toast(msg);

    } catch(e) {
        java.log(e);
        java.toast("已取消音色设置");
    }
}

