<html>
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>头像字体设置</title>
<style>
:root {
    --bg: #0a0a0f;
    --bg-gradient: radial-gradient(ellipse at 30% 20%, #1a1040 0%, #0a0e27 50%, #0d1b3e 100%);
    --text: #e8e8f0;
    --text-secondary: #8888a0;
    --accent: #6c5ce7;
    --accent-glow: rgba(108, 92, 231, 0.4);
