function SourceSelector() {
    try {
        var config = getConfig.call(this);

        var typeToItems = {};
        var typeLabels = { novel: '小说', audio: '听书', comic: '漫画', video: '视频' };
        var typeIcons = {
            novel: 'fa-solid fa-book-open',
            audio: 'fa-solid fa-headphones',
            comic: 'fa-solid fa-images',
            video: 'fa-solid fa-clapperboard'
        };
        var typeKeywords = { novel: '小说', audio: '听书', comic: '漫画', video: '视频' };
        var typeOrder = ['novel', 'audio', 'comic', 'video'];

        try {
            var apiUrl = getServerHost() + '/api/get_config';
            var resp = JSON.parse(java.ajax(apiUrl));
            if (resp && Array.isArray(resp)) {
                resp.forEach(function (item) {
                    if (!item.name || !item.key) return;
                    var t = item.type || 'novel';
                    if (!typeToItems[t]) typeToItems[t] = [];
                    typeToItems[t].push({
                        name: item.name,
                        key: item.key,
                        free: item.free || ''
                    });
                });
            }
        } catch (e) {
            java.toast("获取源站列表失败，请切换服务器后重试");
            return;
        }

        var currentRaw = config.source || '';
        var currentIsAll = false;
        var currentAllType = '';
        for (var k in typeKeywords) {
            if (typeKeywords[k] == currentRaw) {
                currentIsAll = true;
                currentAllType = k;
                break;
            }
        }
        var selectedNames = [];
        if (currentRaw && !currentIsAll) {
            selectedNames = currentRaw.split(',').map(function (s) { return s.trim(); }).filter(function (s) { return s; });
        }
        var selectedSet = {};
        selectedNames.forEach(function (n) { selectedSet[n] = true; });

        var firstType = 'novel';
        if (currentIsAll) {
            firstType = currentAllType;
        } else if (selectedNames.length > 0) {
            for (var t in typeToItems) {
                for (var i = 0; i < typeToItems[t].length; i++) {
                    if (typeToItems[t][i].name == selectedNames[0]) { firstType = t; break; }
                }
                if (firstType == t) break;
            }
        }

        var currentGender = config.gender || 'boy';

        var tabBtnsHtml = '';
        var panelsHtml = '';

        typeOrder.forEach(function (t) {
            var items = typeToItems[t] || [];
            var active = (t == firstType) ? ' active' : '';
            var count = items.length;

            tabBtnsHtml += '<button class="tab-btn' + active + '" data-tab="' + t + '" onclick="switchTab(\'' + t + '\')">'
                         + '<i class="' + typeIcons[t] + '"></i>'
                         + '<span>' + typeLabels[t] + '</span>'
                         + '<em>' + count + '</em>'
                         + '</button>';

            var panel = '<div class="panel' + active + '" id="panel-' + t + '">';
            panel += '<div class="grid">';

            var allSel = (currentIsAll && currentAllType == t) ? ' selected' : '';
            panel += '<div class="src-card all-card' + allSel + '"'
                   + ' data-type="' + t + '" data-name="" data-all="1"'
                   + ' onclick="pick(this)">'
                   + '<span class="src-name"><i class="fa-solid fa-star card-ico"></i>全部</span>'
                   + '</div>';

            items.forEach(function (it) {
                var sel = selectedSet[it.name] ? ' selected' : '';
                var vip = (it.free == 'svip') ? '<span class="vip-tag">VIP</span>' : '';
                panel += '<div class="src-card' + sel + '" data-type="' + t
                       + '" data-name="' + it.name + '" data-all="0"'
                       + ' onclick="pick(this)">'
                       + '<span class="src-name">' + it.name + '</span>'
                       + vip
                       + '</div>';
            });

            panel += '</div></div>';
            panelsHtml += panel;
        });

        var initDisplay = '未选择';
        if (currentIsAll) {
            initDisplay = typeLabels[currentAllType] + ' · 全部';
        } else if (selectedNames.length > 0) {
            initDisplay = selectedNames.join('、');
        }
        var initCount = currentIsAll ? 'ALL' : selectedNames.length;

        var boyActive = (currentGender == 'boy') ? ' active' : '';
        var girlActive = (currentGender == 'girl') ? ' active' : '';

        var host = getServerHost();
        var html = `<!DOCTYPE html>
