// ===== 工具函数 =====
function GET(k) {
  const { java, source } = this;
  var d = {};
  try { d = JSON.parse(source.getVariable() || "{}"); } catch (e) { d = {}; }
  return d[k] || '';
}

function SET(k, v) {
  const { java, source } = this;
  var d = {};
  try { d = JSON.parse(source.getVariable() || "{}"); } catch (e) { d = {}; }
  d[k] = v;
  source.putVariable(JSON.stringify(d, null, '\t'));
}


// ===== 网关鉴权（LoomProxy api_key，登录面板「apikey」输入框录入 → 源变量）=====
// 不内嵌默认 key：未填写时请求不带凭证，由网关返回 401 提示
function LP_KEY() {
  return GET.call(this, 'apikey') || '';
}

function withKey(url) {
  var k = LP_KEY.call(this);
  if (!k) return url;
  return url + (url.indexOf('?') >= 0 ? '&' : '?') + 'api_key=' + k;
}
