// 平台公告
function getAnn() {
  const {java, cache, source} = this;
  // 公告拉取失败不应中断发现页渲染
  try {
    let url = GET.call(this, 'host') + '/announcement';
    let con = cache.get('announcement');
    let resp = JSON.parse(java.ajax(withKey.call(this, url))).data.content;
    if (con && con == resp) return;
    cache.put('announcement', resp);

    if (/书源更新/.test(resp)) {
      SET.call(this, 'updateSource', 1);
    }

    java.longToast('\n平台公告：' + resp);
  } catch (e) { java.log('getAnn: ' + e); }
}

// 获取登录状态
function getLoginSta() {
  var java = this.java, source = this.source;

  let url = GET.call(this, 'host') + '/auth/me';
  let resp = java.ajax(withKey.call(this, url));

  return /ok/.test(resp);
}

