// 分类数据获取：静态字典构建期内嵌进 LP_DATA（运行时零请求），未内嵌的
// 键走 CacheManager 缓存层（先本地后网络，失败回退，仅"无缓存且失败"抛错）。
function getCateData(name, force) {
  const { java, cache } = this;
  var category = GET.call(this, 'category');
  var embedded = (typeof LP_DATA !== 'undefined') && (LP_DATA[name] || LP_DATA[category + '_' + name]);
  if (embedded) return embedded;
  var key = 'syiism_cate_' + category + '_' + name;
  var cached = '';
  try { cached = cache.get(key) || ''; } catch (e) {}
  if (force || !cached) {
    try {
      var url = GET.call(this, 'host') + '/data/' + category + '/' + name + '.json';
      var data = JSON.parse(java.ajax(withKey.call(this, url)));
      try { cache.put(key, JSON.stringify(data)); } catch (e) {}
      return data;
    } catch (e) { java.log('getCateData ' + name + ': ' + e); }
  }
  if (cached) return JSON.parse(cached);
  throw new Error('分类数据 ' + name + ' 拉取失败且无本地缓存');
}

// 初始化源变量（默认本地网关 + fq_hg 小说模式）。原在 loginUrl/exploreUrl
// 各写一份，现收进 jsLib：jsLib 词法上无 source/java 绑定，须从 this 解构
// 首用兜底：装源后未打开过发现/登录页就直接搜索时，补齐必要源变量默认值。
// 只填缺失键、不覆盖已有值；已下线数据源（如番茄五源）自动迁移到默认源并
// 同步刷新 host——否则旧变量会让 loginUi 的 searchTabs[origin] 崩溃成死锁。
function LP_INIT() {
  var defs = {
    host: 'https://loomproxy.dpdns.org',
    origin: 'fq_hg',
    origin_zh: '番茄红果',
    category: 'fq',
    tab_type: 3,
    tone_id: '0',
    module: '小说'
  };
  var d = {};
  try { d = JSON.parse(this.source.getVariable() || '{}') || {}; } catch (e) { d = {}; }
  var changed = false;
  for (var k in defs) { if (!d[k]) { d[k] = defs[k]; changed = true; } }
  var ids = getOrigins().map(function (x) { return x.id; });
  if (d.origin && ids.indexOf(d.origin) < 0) {
    d.origin = defs.origin; d.origin_zh = defs.origin_zh; d.category = defs.category;
    d.tab_type = defs.tab_type; d.module = defs.module; d.bd_id = '-';
    d.originIdx = 0; d.bdTyIdx = 1; d.host = defs.host;
    changed = true;
  }
  if (changed) { try { this.source.setVariable(JSON.stringify(d, null, '\t')); } catch (e2) {} }
}

// 搜索 URL（按 origin 分派参数：fq_hg 走 tabType 默认分流、xmly 无分页、
// 其余 query+page；快捷搜索 +tab_type 前缀解析出的 tabOverride 仅 fq_hg 有效）
function LP_SEARCH_URL(key, page, tabOverride) {
  LP_INIT.call(this);
  var o = GET.call(this, 'origin');
  if (o == 'fq_hg') {
    return withKey.call(this, GET.call(this, 'host') + '/fq_hg/search?query=' + key +
      '&tabType=' + (tabOverride || GET.call(this, 'tab_type')) + '&page=' + (page || 1));
  }
  if (o == 'xmly') {
    return withKey.call(this, GET.call(this, 'host') + '/xmly/search?query=' + key);
  }
  return withKey.call(this, GET.call(this, 'host') + '/' + o + '/search?query=' + key + '&page=' + (page || 1));
}
