function fqOpenComments(p) {
    var api = getApi.call(this);
    var qs = [];
    for (var k in p) {
        if (!Object.prototype.hasOwnProperty.call(p, k)) continue;
        if (p[k] === "" || p[k] == null) continue;
        qs.push(encodeURIComponent(k) + "=" + encodeURIComponent(String(p[k])));
    }
    var url = api + "/comment.html?" + qs.join("&");
    var TITLES = { book: "书评", chapter: "本章讨论", paragraph: "段评" };
    var title = TITLES[p.mode] || "评论";
    var j = fqJava.call(this);

    if (fqHasMethod(j, "showBrowser")) {
        var html = "";
        if (fqHasMethod(j, "ajax")) { try { html = j.ajax(url) || ""; } catch (e) { html = ""; } }
        try { j.showBrowser(url, html); return; } catch (e) { fqLog.call(this, "[评论] showBrowser 失败：" + e); }
    }

    if (fqHasMethod(j, "startBrowser")) {
        try { j.startBrowser(url, title); return; } catch (e) { fqLog.call(this, "[评论] startBrowser 失败：" + e); }
    }
    fqToast.call(this, "无法打开评论页（宿主对象不可用）");
}

function fqBubble(count, paraId, paraText, bookId, chapterId) {
    var st = fqBubbleStyle.call(this);
    var n = Number(count) || 0;
    var txt = n > 999 ? "999" : String(n);
    var svg = '<svg width="150" height="110" xmlns="http://www.w3.org/2000/svg">' +
        '<path d="M 55 10 L 120 10 Q 148 10 148 40 L 148 78 Q 148 106 120 106 L 55 106 Q 27 106 27 78 L 27 73 L 6 58 L 27 43 L 27 38 Q 27 10 55 10 Z" ' +
        'fill="none" stroke="' + st.color + '" stroke-width="5" stroke-linejoin="round"/>' +
        '<text x="87" y="70" font-family="Arial, sans-serif" text-anchor="middle" dominant-baseline="middle" ' +
        'font-size="46" font-weight="bold" fill="' + st.color + '">' + txt + "</text></svg>";
    function esc(s) {
        return String(s == null ? "" : s).replace(/\\/g, "\\\\").replace(/'/g, "\\'").replace(/[\r\n]+/g, " ");
    }
    var opts = {
        style: st.size,
        click: "fqShowParagraph('" + esc(bookId) + "','" + esc(chapterId) + "','" + esc(paraId) + "','" + esc(paraText) + "','" + n + "')"
    };
    return "data:image/svg+xml;base64," + fqBase64.call(this, svg) + "," + JSON.stringify(opts);
}

function fqShowParagraph(bookId, chapterId, paraId, paraText, count) {
    try {
        if (!bookId) bookId = fqBookId.call(this);
        if (!chapterId) chapterId = fqChapterId.call(this);
        fqOpenComments.call(this, {
            mode: "paragraph",
            bookId: bookId,
            chapterId: chapterId,
            paragraphId: paraId,
            paraText: paraText,
            count: count
        });
    } catch (e) { fqToast.call(this, "段评打不开：" + e); }
}
function fqShowChapter(bookId, chapterId) {
    try {
        if (!bookId) bookId = fqBookId.call(this);
        if (!chapterId) chapterId = fqChapterId.call(this);
        fqOpenComments.call(this, { mode: "chapter", bookId: bookId, chapterId: chapterId });
    } catch (e) { fqToast.call(this, "章评打不开：" + e); }
}
function fqShowBook(bookId) {
    try {
        if (!bookId) bookId = fqBookId.call(this);
        fqOpenComments.call(this, { mode: "book", bookId: bookId });
    } catch (e) { fqToast.call(this, "书评打不开：" + e); }
}

function fqBookId() {
    try {
        var b = fqBook.call(this);
        if (b) {
            var u = String(b.bookUrl || b.tocUrl || "");
            var m = u.match(/[?&]id=(\d+)/);
            if (m) return m[1];
        }
    } catch (e) {}
    return "";
}
function fqChapterId() {
    var src = fqBaseUrl.call(this);
    if (!src) return "";
    var m = src.match(/[?&]suffix=([^&]*)/);
    var suffix = m ? m[1] : "";
    if (!suffix) return "";
    try { suffix = decodeURIComponent(suffix); } catch (e) {}
    var c = suffix.match(/chapterId=(\d+)/);
    return c ? c[1] : "";
}

function fqFetchParaStats(bookId, chapterId) {
    if (!bookId || !chapterId) { fqLog.call(this, "[段评] 缺 bookId/chapterId"); return null; }
    try {
        var j = fqJava.call(this);
        if (!fqHasMethod(j, "ajax")) { fqLog.call(this, "[段评] 没有 java.ajax"); return null; }
        var u = getApi.call(this) + "/api/reader/paragraphs?bookId=" + encodeURIComponent(bookId) + "&chapterId=" + encodeURIComponent(chapterId);
        fqLog.call(this, "[段评] " + u);
        var raw = j.ajax(u);
        if (!raw) { fqLog.call(this, "[段评] 接口返回空"); return null; }
        var o = JSON.parse(raw);
        var d = (o && o.data) || null;
        fqLog.call(this, "[段评] 锚点 " + (d ? (d.paragraphs || []).length + " 段" : "无"));
        return d;
    } catch (e) {
        fqLog.call(this, "[段评] 取锚点失败：" + e);
        return null;
    }
}

function fqInjectBubbles(content, bookId, chapterId) {
    var stats = fqFetchParaStats.call(this, bookId, chapterId);
    if (!stats || !stats.paragraphs || !stats.paragraphs.length) return content;
    var paras = stats.paragraphs;
    var lines = String(content).split("\n");
    var textLine = [];
    for (var i = 0; i < lines.length; i++) {
        var t = lines[i].replace(/<[^>]+>/g, "").trim();
        if (!t || /^\s*<img\b/i.test(lines[i])) continue;
        textLine.push(i);
    }

    var edits = [];
    for (var k = 0; k < paras.length; k++) {
        var p = paras[k];
        var cnt = Number(p.commentCount) || 0;
        if (!cnt || !p.paragraphId) continue;
        var lineNo = textLine[k];
        if (lineNo === undefined) continue;
        edits.push({ line: lineNo, img: "<img src=\"" + fqBubble.call(this, cnt, p.paragraphId, lines[lineNo].trim(), bookId, chapterId) + "\">" });
    }
    edits.sort(function (a, b) { return b.line - a.line; });
    for (var e = 0; e < edits.length; e++) {
        lines[edits[e].line] += edits[e].img;
    }
    fqLog.call(this, "[段评] 注入 " + edits.length + " 个气泡");
    return lines.join("\n");
}

