(function(){
var GAP=0.042,PAD=0.080,CH=0.050,COLS=3;
var B=(typeof baseUrl!=='undefined'&&baseUrl)?baseUrl:'https://jable1.nl';
/* 折叠状态存书源变量：tag=1 标签墙展开，mdl=1 人气女优展开 */
var cfg={};
try{cfg=JSON.parse(String(source.getVariable()||'{}'))||{};}catch(e){}
var tagOpen=cfg.tag?true:false;
var mdlOpen=cfg.mdl?true:false;

/* 标题宽度估算（UTF-16，emoji 代理对算 2） */
function tw(s){var w=0,i,o,c;for(i=0;i<s.length;i++){o=s.charCodeAt(i);c=s.charAt(i);
  if(c===' ')w+=0.32;
  else if(o>=0xD800&&o<=0xDBFF)w+=2.0;
  else if(o<128)w+=0.65;
  else if(o===0xB7)w+=0.5;
  else if(o===0x25CF)w+=0.9;
  else w+=1.0;}
  return w;}

/* 不可点击整行标题栏：url 型 + url:'' + 单引号 viewName（长度须 3..19） */
function bar(t){var vn="'"+t+"'";
  if(vn.length<3||vn.length>19){throw new Error('viewName 长度越界 '+vn.length);}
  return {title:t,url:'',viewName:vn,
    style:{layout_flexGrow:1,layout_flexBasisPercent:1,layout_wrapBefore:true}};}

/* 可点击整行开关：type=button + action（不指向任何网络请求） */
function btn(t,key){var vn="'"+t+"'";
  if(vn.length<3||vn.length>19){throw new Error('viewName 长度越界 '+vn.length);}
  var js="(function(){var c={};try{c=JSON.parse(String(source.getVariable()||'{}'))||{};}catch(e){}"
    +"c.__K__=c.__K__?0:1;source.setVariable(JSON.stringify(c));java.refreshExplore();})()";
  return {title:t,url:'',type:'button',action:js.split('__K__').join(key),viewName:vn,
    style:{layout_flexGrow:1,layout_flexBasisPercent:1,layout_wrapBefore:true}};}

/* 导航按钮：URL 自带 {{page}}，第 1 页无后缀，第 N 页补 N/（站点分页须带尾斜杠） */
function nav(t,p){return {title:t,url:B+p+"{{page>1?page+'/':''}}"};}

/* 等宽格 + first-fit 折行 + 行尾补位 */
function pack(items){
  var cell=(1-GAP*(COLS-1))/COLS, fit=(cell-PAD)/CH;
  var q=[],i,sp;
  for(i=0;i<items.length;i++){
    sp=Math.min(COLS,Math.max(1,Math.ceil(tw(items[i].title)/fit)));
    q.push({title:items[i].title,url:items[i].url,span:sp});}
  var out=[];
  while(q.length){
    var row=[],left=COLS,k,x;
    while(q.length&&left>0){
      k=0;while(k<q.length&&q[k].span>left)k++;
      if(k===q.length)break;
      x=q.splice(k,1)[0];row.push(x);left-=x.span;}
    while(left>0){row.push({title:'　',url:'',span:1});left--;}
    for(i=0;i<row.length;i++){
      row[i].style={layout_flexGrow:row[i].span,
        layout_flexBasisPercent:Math.round((row[i].span/(COLS+1)+(row[i].span-1)*GAP)*1e4)/1e4,
        layout_wrapBefore:(i===0)};}
    out=out.concat(row);}
  return out;}

