  var page = (String(baseUrl || '').match(/[#&]page=([^&,]+)/) || [])[1] || '1';
  if (Number(page) > 1 && qmSection) {
    return JSON.stringify({data: []});
  }
  if (d.sections && d.sections.length > 0) {
    if (qmSection) {
      for (var s = 0; s < d.sections.length; s++) {
        var sec = d.sections[s] || {};
        var header = sec.section_header || {};
        if (String(header.position) === qmSection) {
          list = sec.playlet_list || [];
          break;
        }
      }
    } else {
      list = d.playlet_list || d.list || d.books || [];
      if ((!list || list.length === 0) && d.sections.length > 0) {
        list = d.sections[0].playlet_list || [];
