function login(){}
function fqLvGetPara() {
    try {
        var v = String(source.getVariable() || '{}');
        var d = JSON.parse(v);
        return d && d.showPara ? String(d.showPara) : '0';
    } catch (e) { return '0'; }
}
function fqLvTogglePara() {
    var cur = fqLvGetPara();
    var val = cur === '1' ? '0' : '1';
    try { source.setVariable((function () {
        var d = {};
        try { d = JSON.parse(String(source.getVariable() || '{}')); } catch (e) { d = {}; }
        if (!d.pool || !d.pool.sessions) { d.pool = { sessions: [], cursor: 0 }; }
        d.showPara = val;
        return JSON.stringify(d);
    })()); } catch (e) {}
    java.toast(val === '1' ? '💬 段评已开启\n刷新正文后生效' : '🚫 段评已关闭');
    fqLvRefresh();
}
// ---- 气泡社区：自定义段评气泡 ----
function fqLvGetSync() {
    try {
        var d = fqLvState();
        return d && d.syncBubble ? String(d.syncBubble) : '0';
    } catch (e) { return '0'; }
}
function fqLvToggleSync() {
    var val = fqLvGetSync() === '1' ? '0' : '1';
    var d = fqLvState();
    d.syncBubble = val;
    fqLvSave(d);
    java.toast(val === '1' ? '☁️ 气泡社区同步已开启\n读正文时自动拉取自定义气泡' : '🚫 气泡社区同步已关闭\n恢复默认气泡');
    fqLvRefresh();
}
// 打开气泡社区选气泡，并置 syncBubble=1（下次读正文时同步气泡模板）
function fqLvOpenCommunity() {
    var d = fqLvState();
    d.syncBubble = '1';
    fqLvSave(d);
    try { java.startBrowser('https://marginly.dpdns.org/', '气泡社区'); } catch (e) { java.toast('打开失败：' + String(e)); }
    fqLvRefresh();
}

function fqLvState() {
    var d = {};
    try { d = JSON.parse(String(source.getVariable() || '{}')); } catch (e) { d = {}; }
    if (!d || typeof d !== 'object') { d = {}; }
    if (!d.pool || !d.pool.sessions) { d.pool = { sessions: [], cursor: 0 }; }
    return d;
}
function fqLvSave(d) { try { source.setVariable(JSON.stringify(d)); } catch (e) {} }
// 刷新登录页状态（按钮文案/状态行随源变量更新）
function fqLvRefresh() { try { java.reLoginView(); } catch (e) {} }
// 登录页菜单分支切换：FQ_SET 写入源变量（经 fqUseSource 桥接 jsLib），再刷新面板
function fqLvSetMenu(m) {
    var ok = false;
    try { fqUseSource(source); FQ_SET('login_menu', String(m)); ok = true; } catch (e1) { ok = false; }
    if (!ok) { try { var d = fqLvState(); d.login_menu = String(m); fqLvSave(d); } catch (e2) {} }
    fqLvRefresh();
}
function fqLvBegan() {
    // 固定设备：经 jsLib（SharedJsScope 原型链可见）取构建期注入的设备，初始化即写入源变量（无注册）
    var pool = { sessions: [], cursor: 0 };
    try { fqUseSource(source); pool = fqFixedPool(); } catch (eP) { pool = { sessions: [], cursor: 0 }; }
    fqLvSave({ site: 'fq', mode: '小说', tab_type: '3', explore_pick: '小说', tone_id: '1', pool: pool, showPara: '0', showChap: '0', syncBubble: '0', bbSvg: '', login_menu: 'main' });
    java.toast('已初始化源变量\n默认：小说\n固定设备已写入（无注册）');
    fqLvRefresh();
}
// 模式表：合并双站重叠后的 5 形态（与 jsLib 的 MODE_CFG 保持一致）
var FQLV_MAP = {
    '小说': ['fq', '3'], '听书': ['fq', '2'], '漫画': ['fq', '8'],
    '短剧': ['hg', '10'], '漫剧': ['hg', '13']
};
var FQLV_TONES = [["默认","1"],["真人","0"],["甜美少女","1"],["清亮青叔","2"],["成熟大叔","4"],["开朗青年","5"],["温柔淑女","6"],["风雅青叔","8"],["清纯少女","12"],["磁性青叔","17"],["推文女声","27"],["亲切姐姐","28"],["儒雅大叔","29"],["优雅御姐","30"],["斯文青叔","31"],["知性主播","32"],["多人对话","51"],["成熟升级","74"],["俏皮御姐","100"],["双音灵动","103"],["王明军音","105"]];
function fqLvSetTone(n) {
    var d = fqLvState();
    d.tone_id = String(n);
    // 按按钮预设音色时清除自定义音色，避免两者同时存在造成歧义
    if (d.tone_custom) { delete d.tone_custom; }
    fqLvSave(d);
    var nm = '';
    for (var i = 0; i < FQLV_TONES.length; i++) { if (FQLV_TONES[i][1] === String(n)) { nm = FQLV_TONES[i][0]; break; } }
    java.toast('音色已切换：' + (nm || n) + '（tone_id=' + n + '）\n听书正文刷新后生效');
    fqLvRefresh();
}
function fqLvSetPresetTone(n) { fqLvSetTone(n); }
// 保存自定义音色 ID（从 text 输入框触发）：写入 tone_custom，清空 tone_id
function fqLvSaveCustomTone() {
    var raw = source.getLoginInfoMap().get('自定义 toneId');
    var val = (raw || '').trim();
    if (!val) { java.toast('音色 ID 不能为空'); return; }
    var d = fqLvState();
    d.tone_custom = val;
    if (d.tone_id) { delete d.tone_id; }
    fqLvSave(d);
    java.toast('自定义音色已保存：toneId=' + val + '\n听书正文刷新后生效');
    fqLvRefresh();
}
// 读取当前有效音色（优先自定义 tone_custom，其次 preset tone_id，最后回退默认 1）
function fqLvCurToneDisplay() {
    var d = fqLvState();
    if (d.tone_custom) { return d.tone_custom; }
    return String(d.tone_id || '1');
}
function fqLvToneInfo() {
    var d = fqLvState();
    var cur = fqLvCurToneDisplay();
    // 若是内置音色表里的 id，显示名称；否则原样输出（自定义 ID 可能不在表内）
    var nm = '';
    for (var i = 0; i < FQLV_TONES.length; i++) { if (FQLV_TONES[i][1] === cur) { nm = FQLV_TONES[i][0]; break; } }
    var tag = d.tone_custom ? ' [自定义]' : '';
    java.toast('当前音色：' + (nm || ('(ID=' + cur + ')')) + tag + '（tone_id=' + cur + '）');
}
function fqLvSetMode(t) {
    var m = FQLV_MAP[t];
    if (!m) { java.toast('未知模式：' + t); return; }
    var d = fqLvState();
    d.site = m[0]; d.tab_type = m[1]; d.mode = t; d.explore_pick = t;
    d.mode_override = '1';   // 标记主动切换：正文/目录优先用源变量 tab_type，忽略 bookUrl 旧模式快照
    fqLvSave(d);
    java.toast('已切换：' + t + '\n刷新目录/正文后生效');
    fqLvRefresh();
}
function fqLvPoolInfo() {
    var d = fqLvState();
    var pool = d.pool;
    var lines = ['固定设备：' + pool.sessions.length + ' 台（构建期注入，无注册；cursor=' + pool.cursor + '）'];
    for (var i = 0; i < pool.sessions.length; i++) {
        var s = pool.sessions[i];
        var ks = [];
        for (var aid in s.keys) { if (s.keys.hasOwnProperty(aid)) { ks.push('aid' + aid + ' v' + String(s.keys[aid].ver)); } }
        lines.push((i + 1) + '. ' + String(s.device.device_id) + (ks.length ? ' ' + ks.join(' ') : ' 未注册密钥'));
    }
    lines.push('站点：' + (d.site || 'hg') + '  模式：' + (d.mode || '-') + '（tab_type=' + (d.tab_type || '10') + '）');
    java.longToast(lines.join(String.fromCharCode(10)));
}
function fqLvPoolClean() {
    var d = fqLvState();
    d.pool = { sessions: [], cursor: 0 };
    fqLvSave(d);
    java.toast('设备池已清空\n读正文时用产物内固定设备重新播种');
}
if (String(source.getVariable() || '') === '') { fqLvBegan(); }

