ruleBookInfo.intro:
@js:(function(){try{fqUseSource(source);}catch(e){}
  var j = {};
  try { j = JSON.parse(String(result || '{}')); } catch (eJ) {}
  var raw = j.__raw || {};
  var L = [];
  function pushRow(label, val) {
    var s = String(val === undefined || val === null ? '' : val).replace(/<[^>]+>/g, '').trim();
    if (s) { L.push('<br/>' + label + '：' + s); }
  }
  var abstract = String(raw.abstract || raw.book_abstract_v2 || '').replace(/<[^>]+>/g, '').trim();
  L.push('<br/><br/>📜 简介');
  L.push('<br/>' + (abstract || '暂无简介'));
  // 编号 / 源名 / 别名（别名字段可能不存在）
  pushRow('🆔 编号', raw.book_id);
  pushRow('📕 源名', raw.original_book_name);
  pushRow('📔 别名', raw.book_flight_alias_name || raw.op_book_name);
  // 状态：creation_status 0=连载中 1=完结 2=断更（与番茄惯例一致）
  var st = '';
  var cs = Number(raw.creation_status === undefined ? raw.status : raw.creation_status);
  st = cs === 0 ? '连载中' : (cs === 1 ? '已完结' : (cs === 2 ? '断更' : String(raw.status || '')));
  pushRow('📇 状态', st);
  // 开坑 / 更新：create_time 为 ISO 串，last_chapter_update_time 为秒级时间戳
  var ct = String(raw.create_time || '');
  if (ct && ct.length >= 10) { ct = ct.substring(0, 10); }
  pushRow('✏️ 开坑', ct);
  var lu = Number(raw.last_chapter_update_time || 0);
  if (lu > 0) {
    try {
      var luD = new Date(lu * 1000);
      var luM = luD.getMonth() + 1, luDay = luD.getDate();
      var luS = luD.getFullYear() + '-' + (luM < 10 ? '0' + luM : '' + luM) + '-' + (luDay < 10 ? '0' + luDay : '' + luDay);
      pushRow('🕰 更新', luS);
    } catch (eT) {}
  }
  // 字数 / 分类（category 空时回退 category_v2 名称；category_v2 可能是字符串化 JSON）
  pushRow('⌨️ 字数', Number(raw.word_number || 0) > 0 ? fqFmtWan(Number(raw.word_number)) + '字' : '');
  var cat = String(raw.category || '');
  if (!cat && raw.category_v2) {
    var cnames = [];
    var cvs = raw.category_v2;
    if (typeof cvs === 'string') { try { cvs = JSON.parse(cvs); } catch (eC) { cvs = null; } }
    if (cvs && cvs.length) {
      for (var ci = 0; ci < cvs.length; ci++) { var cn = cvs[ci]; if (cn && cn.Name) { cnames.push(cn.Name); } }
    }
    cat = cnames.join('、');
  }
  pushRow('📎 分类', cat);
  pushRow('🏷️ 标签', raw.tags || raw.high_quality_tags);
  // 主角：role 是单个字符串（原始值），roles 才是数组
  if (raw.role !== undefined && raw.role !== null && String(raw.role).length) { pushRow('👤 主角', raw.role); }
  else if (raw.roles !== undefined && raw.roles !== null) { pushRow('👤 主角', raw.roles); }
  // 当前模式 / 当前音色 / 可选音色（音色直接用 tones 原始值）
  var mode = FQ_GET('mode') || FQ_GET('explore_pick') || '';
  pushRow('⚙️ 当前模式', mode);
  var tid = String(FQ_GET('tone_id') || '1');
  var toneName = FQ_TONE_NAMES[Number(tid)] || ('音色' + tid);
  pushRow('🗣 当前音色', toneName);
  // 自定义音色：若 loginUi 中手动填写并保存了 tone_custom，额外显示一行
  var customTone = '';
  try { customTone = String(FQ_GET('tone_custom') || ''); } catch (eCT) { customTone = ''; }
  if (customTone && customTone !== 'null' && customTone !== 'undefined' && customTone !== '') {
    var customName = FQ_TONE_NAMES[Number(customTone)] || ('(自定义 ID=' + customTone + ')');
    pushRow('🎛 自定义音色', customName + ' [toneId=' + customTone + ']');
  }
  var tonesRaw = String(raw.tones || '');
  if (tonesRaw) { pushRow('🔊 可选音色', tonesRaw + (tonesRaw.split(',').length > 10 ? ' 等' : '')); }
  // 评分 / 在线 / 源站 / 书评（响应不一定有）/ 版权
  pushRow('📊 评分', raw.score);
  pushRow('👁️ 在线', raw.sub_info || (Number(raw.read_count) ? fqFmtWan(Number(raw.read_count)) + '人在读' : ''));
  pushRow('🔗 源站', raw.source);
  pushRow('📝 书评', raw.book_review);
  pushRow('📍 版权', raw.copyright_info);
  return L.join('');
})()

