ruleContent.content:
@js:(function(){try{fqUseSource(source);try{fqUseJava(java);}catch(eJ){}}catch(e){}
  var chUrl = (chapter && chapter.url) ? String(chapter.url) : '';
  var bookUrl = (book && book.bookUrl) ? String(book.bookUrl) : '';
  if (!chUrl) { chUrl = String(baseUrl || ''); }
  var ctx = fqParseCtx(bookUrl || chUrl);
  var itemId = fqParseItem(chUrl, bookUrl);
  if (!itemId) { return '未找到章节ID'; }
  var kind = fqTabKind(ctx.tab);
  try {
    // 听书：直链（tone_id 取登录面板选择的音色）
    if (kind === 'audio') { return fqAudioUrl(itemId, FQ_GET('tone_id')); }
    // 视频：CENC 取流取 key → 正文返回 URL 文本，当前章节自动弹播放页（WebView 内解密）
    if (kind === 'video') {
      var vr = fqResolveContent(ctx.tab, itemId, ctx.bookId);
      if (!vr.url) { return '视频流解析失败'; }
      if (book && chapter && book.durChapterIndex == chapter.index) {
        // 选集列表：拉目录 JSON 取各集 itemId（仅当前集弹播放页时一次请求）
        var epList = [];
        try {
          var tocArr = fqTocList(java.ajax(fqTocUrl(ctx.bookId)), ctx.tab);
          for (var ei = 0; ei < tocArr.length; ei++) {
            var ec = JSON.parse(tocArr[ei]);
            var eid = fqParseItem(ec.url, '');
            if (!eid) { continue; }
            epList.push({ id: eid, t: String(ec.title || ('第' + (ei + 1) + '集')) });
          }
        } catch (ecl) { java.log('选集列表获取失败: ' + String(ecl && ecl.message || ecl)); }
        var curIdx = 0;
        for (var ci = 0; ci < epList.length; ci++) {
          if (String(epList[ci].id) === String(itemId)) { curIdx = ci; break; }
        }
        var rate0 = Number(FQ_GET('play_rate')) || 1;
        var html = fqCencPlayerHtml(
          (book && book.name) ? book.name : (chapter && chapter.title ? chapter.title : '视频'),
          vr.url, vr.keyHex, vr.size,
          epList, curIdx, '', ctx.tab, ctx.bookId, rate0
        );
        java.startBrowser('about:blank', book.name || chapter.title || '视频', html);
        java.toast('正在加载并解密视频\n大文件加载较慢，请耐心等待');
      }
      return vr.url;
    }
    // 漫画：免解密入口图集转 <img> 序列（图片均为 web_uri 直链，无解密）
    if (kind === 'comic') {
      var cr = fqComicContent(itemId);
      var out = [];
      for (var i = 0; i < cr.pages.length; i++) {
        var p = cr.pages[i];
        var pu = typeof p === 'string' ? p : (p.picUrl || p.url || '');
        if (!pu) { continue; }
        out.push('<img src="' + pu + '" />');
      }
      return out.join('\n');
    }
    // 文本：只走免解密入口
    var tr = fqResolveContent(ctx.tab, itemId, ctx.bookId);
    // 文本模式下上游可能返回漫画/视频形态（如 fq 发现页混入漫画书），按实际 kind 分发
    if (tr.kind === 'comic') {
      var pages = [];
      for (var q = 0; q < (tr.pages || []).length; q++) {
        var pg = tr.pages[q];
        var pu2 = typeof pg === 'string' ? pg : (pg.picUrl || pg.url || '');
        if (pu2) { pages.push('<img src="' + pu2 + '" />'); }
      }
      return pages.join('\n') || '正文为空';
    }
    if (tr.kind === 'video' && tr.url) { return tr.url; }
    // 气泡社区同步：登录页「气泡社区」按钮置 syncBubble=1，读正文时拉取自定义气泡模板
    if (FQ_GET('syncBubble') == 1) {
      var bbNew = '';
      try {
        var bbTxt = String(java.ajax(FQ_EP.bubbleCommunityApi) || '').trim();
        var bbPlain = bbTxt;
        if (bbTxt.charAt(0) === '{') {
          try {
            var bbJson = JSON.parse(bbTxt);
            if (bbJson && (bbJson.code === 0 || bbJson.code === '0') && bbJson.data) {
              bbPlain = typeof bbJson.data === 'string' ? bbJson.data : String(bbJson.data.svg || '');
            } else { bbPlain = ''; }
          } catch (ebj) { bbPlain = bbTxt.replace(/\"/g, '"'); }
        }
        var bbS0 = bbPlain.indexOf('<svg');
        var bbS1 = bbPlain.lastIndexOf('</svg>');
        if (bbS0 >= 0 && bbS1 > bbS0) { bbNew = bbPlain.substring(bbS0, bbS1 + 6); }
      } catch (ebb) { bbNew = ''; }
      FQ_SET('bbSvg', bbNew);
      FQ_SET('syncBubble', 0);
    }
    // 段评气泡注入（仅文本模式 + showPara 开关打开）。
    // 段评请求统一走 fqHttp（HttpURLConnection 阻塞调用），不依赖 java 桥——评论面板经 run() 桥
    // 回源时 FQ_JAVA 是过期对象，java.ajax 会抛 kotlinx.coroutines.JobCancellationException，
    // 故 fetch.js 的 fqCommentPost 不允许改回 java.ajax（除非同时保证每次求值都刷新桥）。
    var content = String(tr.content || '正文为空');
    if (FQ_GET('showPara') === '1' && tr.kind === 'text' && ctx.bookId) {
      try {
        fqSyncParaStyle();   // 登录页段评设置（气泡颜色/字体颜色/大小）→ 源变量
        var bubbles = fqParaBubbles(ctx.bookId, itemId);
        if (bubbles.length > 0) {
          // 段落分割：参考番茄案例，<p>标签时以<p>为分隔符，否则以换行分隔
          var separator = '\n';
          if (/<p>/.test(content)) {
          	 content = content.replace(/<p><\/p>/g,'');
            content = content.replace('<p>','').replace(/<\/p>/g, '').replace('\n', '');
            separator = '<p>';
          } else {
            content = content.replace(/\r/g, '').replace(/\n$/, '');
          }
          var paras = content.split(separator);
          java.log(paras.length)
          for (var pi = 0; pi < paras.length; pi++) {
            paras[pi] = paras[pi].replace(new RegExp('[\r\n]', 'g'), '').trim();
          }
          for (var bi = 0; bi < bubbles.length; bi++) {
            var b = bubbles[bi];
            if (b.index < paras.length && paras[b.index]) {
              paras[b.index] = paras[b.index]
                + '<img src="' + fqCreateParaBubbleSvg(java, b.count, ctx.bookId, itemId, b.index) + '">';
            }
          }
          content = paras.join(separator);
        }
      } catch (eb) { java.log('段评气泡注入失败: ' + String(eb && eb.message || eb)); }
    }
    return content;
  } catch (e) {
    return '内容获取失败：' + String(e && e.message || e);
  }
})()

