function qmSourceOf(ctx) {
  try {
    if (ctx && ctx.source) return ctx.source
  } catch (e) {}
  try {
    if (typeof source != 'undefined' && source) return source
  } catch (e2) {}
  return null
}

function qmBookOf(ctx) {
  try {
    if (ctx && ctx.book) return ctx.book
  } catch (e) {}
  try {
    if (typeof book != 'undefined' && book) return book
  } catch (e2) {}
  return null
}

function qmCallable(o, n) {
  try {
    return !!o && typeof o[n] == 'function'
  } catch (e) {
    return false
  }
}

function qmJavaOf(ctx) {
  var c = null;
  try {
    c = ctx && ctx.java ? ctx.java : null
  } catch (e) {}
  if (c && qmCallable(c, 'ajax')) return c;
  try {
    c = typeof java != 'undefined' ? java : null
  } catch (e2) {}
  if (c && qmCallable(c, 'ajax')) return c;
  return null
}

function qmSetAudioType(ctx) {
  var bk = qmBookOf(ctx);
  if (bk) {
    try {
      bk.type = 32
    } catch (e) {}
    try {
      bk.originType = 32
    } catch (e2) {}
  }
  return bk
}

function qmToast(m) {
  try {
    var j = qmJavaOf(this);
    if (j) {
      if (qmCallable(j, 'longToast')) {
        j.longToast(String(m));
        return ' '
      }
      if (qmCallable(j, 'toast')) {
        j.toast(String(m));
        return ' '
      }
    }
  } catch (e) {}
  return ' '
}

function qmEsc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;')
}

function qmIntroMode() {
  var s = qmSourceOf(this);
  try {
    var m = String(s.get('qm_intro_mode') || 'beautify');
    if (m === 'text' || m === 'beautify') return m
  } catch (e) {}
  return 'beautify'
}

function qmHasRealVoice(v) {
  if (!v || !v.length) return false;
  for (var i = 0; i < v.length; i++) {
    if (String(v[i].voice_type) === '3' && v[i].voice_url) return true
  }
  return false
}

function qmPickDefaultAIVoice(v) {
  if (!v || !v.length) return '';
  var f = '';
  for (var i = 0; i < v.length; i++) {
    var x = v[i] || {};
    var vid = String(x.voice_id || '');
    var vt = String(x.voice_type);
    if (vid === '200') continue;
    if (vt === '5' || vt === '9') {
      if (vid === '10') return '10';
      if (!f) f = vid
    }
  }
  return f
}

function qmCheckVoiceSupport(v, cfg) {
  if (!cfg || !v || !v.length) return true;
  for (var i = 0; i < v.length; i++) {
    if (String(v[i].voice_id) === String(cfg)) return true
  }
  var a = [];
  for (var j = 0; j < v.length; j++) {
    var x = v[j] || {};
    if (String(x.voice_id) === '200') continue;
    if (x.voice_id) a.push(String(x.voice_id) + (x.voice_name ? '（' + x.voice_name + '）' : ''))
  }
  var t = '⚠️ 本书不支持音色ID「' + cfg + '」\n';
  if (a.length) t += '本书可用：' + a.join('、');
  else t += '本书未提供可用音色';
  return t
}

function qmPadTime(n) {
  n = String(Math.floor(n));
  while (n.length < 2) n = '0' + n;
  return n
}

function qmExtractCaptionItems(c) {
  if (!c) return [];
  var it = c;
  if (c.data && c.data.list) it = c.data.list;
  else if (c.data && c.data.captions) it = c.data.captions;
  else if (c.data && c.data.sentences) it = c.data.sentences;
  else if (c.list) it = c.list;
  else if (c.captions) it = c.captions;
  else if (c.sentences) it = c.sentences;
  if (!it || !it.length) return [];
  return it
}

function qmExtractSubLines(i) {
  if (!i) return [];
  if (i.ss && i.ss.length) return i.ss;
  if (i.subtitles && i.subtitles.length) return i.subtitles;
  if (i.lines && i.lines.length) return i.lines;
  if (i.sentences && i.sentences.length) return i.sentences;
  if (i.items && i.items.length) return i.items;
  return [i]
}

function qmReadTime(c) {
