function qmDetectUnit(items) {
  var s = [];
  for (var i = 0; i < items.length; i++) {
    var ss = qmExtractSubLines(items[i]);
    for (var j = 0; j < ss.length; j++) {
      var t = qmReadTime(ss[j]);
      if (!isNaN(t)) s.push(t)
    }
  }
  if (s.length < 2) return 'ms';
  s.sort(function(a, b) {
    return a - b
  });
  var mx = s[s.length - 1];
  if (mx < 1000) return 's';
  if (mx > 100000) return 'ms';
  var d = [];
  for (var k = 1; k < s.length; k++) {
    var x = s[k] - s[k - 1];
    if (x > 0) d.push(x)
  }
  if (!d.length) return 'ms';
  d.sort(function(a, b) {
    return a - b
  });
  var md = d[Math.floor(d.length / 2)];
  return md < 100 ? 's' : 'ms'
}

function qmCaptionToLrc(c) {
  var it = qmExtractCaptionItems(c);
  if (!it.length) return '';
  var u = qmDetectUnit(it);
  var ls = [];

  function p(st, tx) {
    tx = String(tx || '').replace(/\r?\n/g, ' ').trim();
    if (!tx) return;
    var t = Number(st);
    if (isNaN(t)) t = 0;
    if (u === 's') t = t * 1000;
    var mn = Math.floor(t / 60000);
    var sc = Math.floor((t % 60000) / 1000);
    var cs = Math.floor((t % 1000) / 10);
    ls.push('[' + qmPadTime(mn) + ':' + qmPadTime(sc) + '.' + qmPadTime(cs) + ']' + tx)
  }
  for (var i = 0; i < it.length; i++) {
    var ss = qmExtractSubLines(it[i]);
    for (var j = 0; j < ss.length; j++) {
      p(qmReadTime(ss[j]), qmReadText(ss[j]))
    }
  }
  return ls.join('\n')
}

