function qmParseAlbumInfo(t, baseUrl) {
  var ctx = this;
  qmSetAudioType(ctx);
  var d = qmParse(t).data || {};
  var b = d.book || {};
  var aid = qmUrlValue(baseUrl, 'album_id');
  var v = qmFetchVoiceList.call(ctx, aid);
  var cfg = qmGetVoiceId.call(ctx, aid);
  var k = '';
  if (b.book_tag_list && b.book_tag_list.length) k = b.book_tag_list.map(function(x) {
    return x.title
  }).join(',');
  var m = qmIntroMode.call(ctx);
  var intro = (m === 'text') ? qmBuildAlbumInfoText(d, v, cfg, aid) : qmBuildAlbumInfoHtml(d, v, cfg, aid);
  return {
    name: b.title || '',
    author: b.author || '',
    coverUrl: b.thumb_image_link || b.image_link || '',
    intro: intro,
    kind: k,
    lastChapter: b.chapter_list_desc || '',
    tocUrl: qmAlbumTocUrl.call(ctx, aid)
  }
}

function qmParseAlbumToc(t, baseUrl) {
  var ctx = this;
  qmSetAudioType(ctx);
  var aid = qmUrlValue(baseUrl, 'album_id');
  var r = [],
    seen = {};

  function push(i, fi) {
    i = i || {};
    var cid = i.id || i.chapter_id || '';
    if (!cid) return;
    cid = String(cid);
    if (seen[cid]) return;
    seen[cid] = 1;
    var name = i.title || i.chapter_title || '';
    if (!name) {
      var idx = i.index || i.chapter_sort || (fi + 1);
      name = '第' + idx + '章'
    }
    var dur = i.duration ? ('时长 ' + i.duration) : ('字数 ' + (i.words || '--'));
    r.push({
      name: String(name),
      url: qmAlbumInfoUrl.call(ctx, aid, cid),
      updateTime: dur
    })
  }
  try {
    var d = qmParse(t).data || {};
    var l = d.chapter_list || d.chapter_lists || d.list || d.chapters || [];
    for (var i = 0; i < l.length; i++) push(l[i], i)
  } catch (e) {}
  if (r.length === 0 && aid) {
    try {
      var j = qmJavaOf(ctx);
      if (j) {
        var nr = qmParse(j.ajax(qmNovelChapterListUrl.call(ctx, aid)));
        var nd = nr.data || {};
        var nl = nd.chapter_lists || nd.chapter_list || nd.list || nd.chapters || [];
        for (var n = 0; n < nl.length; n++) push(nl[n], n)
      }
    } catch (e2) {}
  }
  if (r.length === 0 && aid) {
    try {
      var j2 = qmJavaOf(ctx);
      if (j2) {
        var dr = qmParse(j2.ajax(qmAlbumDetailUrl.call(ctx, aid)));
        var dd = dr.data || {};
        var dl = dd.chapter_list || dd.chapter_lists || dd.list || dd.chapters || [];
        for (var k = 0; k < dl.length; k++) push(dl[k], k)
      }
    } catch (e3) {}
  }
  if (r.length === 0) r.push({
    name: '🎧 点击播放（该专辑无章节数据）',
    url: qmAlbumInfoUrl.call(ctx, aid, ''),
    updateTime: '整本播放'
  });
  return r
}

function qmParseAlbumContent(t, baseUrl) {
  qmSetAudioType(this);
  var d = qmParse(t).data || {};
  var v = d.voice_list || [];
  var aid = qmUrlValue(baseUrl, 'album_id');
  var cid = qmUrlValue(baseUrl, 'chapter_id');
  var cfg = qmGetVoiceId.call(this, aid);
  var hr = qmHasRealVoice(v);
  var ap = false;
  if (!cfg && !hr) {
    var a = qmPickDefaultAIVoice(v);
    if (a) {
      cfg = a;
      ap = true
    }
  }
  if (cfg === '200') return qmToast.call(this, '音色200服务端无音频，请改用10');
  if (cfg) {
    var ck = qmCheckVoiceSupport(v, cfg);
    if (ck !== true) return qmToast.call(this, ck)
  }
  var isAI = false;
  if (cfg) {
    for (var x = 0; x < v.length; x++) {
      if (String(v[x].voice_id) === cfg) {
        var vt = String(v[x].voice_type);
        if (vt === '5' || vt === '9') isAI = true;
        else if (v[x].voice_url) {
          var s0 = qmSourceOf(this);
          if (s0) {
            try {
              s0.put('qm_used_voice_' + aid + '_' + cid, cfg)
            } catch (e0) {}
          }
          return String(v[x].voice_url)
        }
        break
      }
    }
  }
  if (cfg && isAI) {
    var s = qmSourceOf(this);
    var ck2 = 'qm_tts_' + aid + '_' + cfg + '_' + cid;
    var ca = s.get(ck2);
    if (ca && ca.indexOf('http') === 0) {
      if (ap) qmToast.call(this, '已自动使用 AI 音色 [' + cfg + ']');
      return ca
    }
    try {
      var j = qmJavaOf(this);
      var bid = String((d.book && d.book.id) || aid || '');
      if (!bid) return '';
      var tr = qmParse(j.ajax(qmNovelChapterListUrl.call(this, bid)));
      var nd = tr.data || {};
      var nl = nd.chapter_lists || nd.chapter_list || nd.list || nd.chapters || [];
      if (!nl.length) return '';
      var ar = null;
      try {
        ar = qmParse(j.ajax(qmAlbumTocUrl.call(this, aid)))
      } catch (eA) {}
      var al = ar && ar.data ? (ar.data.chapter_list || ar.data.chapter_lists || ar.data.list || ar.data.chapters || []) : [];
      var ci = -1;
      for (var ni = 0; ni < nl.length; ni++) {
        if (String(nl[ni].id) === String(cid)) {
          ci = ni;
          break
        }
      }
      if (ci < 0) {
        var cix = '';
        for (var ai2 = 0; ai2 < al.length; ai2++) {
          if (String(al[ai2].id) === String(cid)) {
            cix = String(al[ai2].index || '');
            break
          }
        }
        if (cix) {
          for (var ni2 = 0; ni2 < nl.length; ni2++) {
            if (String(nl[ni2].index || '') === cix) {
              ci = ni2;
              break
            }
          }
        }
      }
      if (ci < 0) ci = 0;
      var bai = [],
        bni = [],
        bm = [];
      var ei = Math.min(ci + 10, nl.length);
      for (var bi = ci; bi < ei; bi++) {
        var nc = nl[bi] || {};
        var nid = String(nc.id || '');
        var md = String(nc.content_md5 || '');
        if (!nid || !md) continue;
        var nix = String(nc.index || '');
        var ai3 = '';
        for (var aj = 0; aj < al.length; aj++) {
          if (String(al[aj].index || '') === nix) {
            ai3 = String(al[aj].id);
            break
          }
        }
        if (!ai3) ai3 = nid;
        bai.push(ai3);
        bni.push(nid);
        bm.push(md)
      }
      if (!bni.length) return '';
      var pu = qmPreloadUrl.call(this, bid, bni.join(','), bm.join(','), cfg);
      var pr = qmParse(j.ajax(pu));
      var pd = pr.data || {};
      var pl = pd.chapter_list || pd.list || [];
      var cu = '';
      for (var pi = 0; pi < pl.length; pi++) {
        var it = pl[pi] || {};
        var ini = String(it.chapter_id || it.id || '');
        if (!ini || !it.voice_url) continue;
        for (var qi = 0; qi < bni.length; qi++) {
          if (bni[qi] === ini) {
            s.put('qm_tts_' + aid + '_' + cfg + '_' + bai[qi], String(it.voice_url));
            if (String(bai[qi]) === String(cid)) {
              cu = String(it.voice_url);
              s.put('qm_used_voice_' + aid + '_' + cid, cfg)
            }
            break
          }
        }
      }
      if (cu) {
        if (ap) qmToast.call(this, '已自动使用 AI 音色 [' + cfg + ']');
        return cu
      }
      for (var pj = 0; pj < pl.length; pj++) {
        if (pl[pj] && pl[pj].voice_url) {
          s.put(ck2, String(pl[pj].voice_url));
          s.put('qm_used_voice_' + aid + '_' + cid, cfg);
          if (ap) qmToast.call(this, '已自动使用 AI 音色 [' + cfg + ']');
          return String(pl[pj].voice_url)
        }
      }
      return ''
    } catch (e) {
      return ''
    }
  }
  for (var i = 0; i < v.length; i++) {
    if (String(v[i].voice_type) === '3' && v[i].voice_url) {
      var s3 = qmSourceOf(this);
      if (s3) {
        try {
          s3.put('qm_used_voice_' + aid + '_' + cid, String(v[i].voice_id || ''))
        } catch (e3) {}
      }
      return String(v[i].voice_url)
    }
  }
  for (var k = 0; k < v.length; k++) {
    if (v[k].voice_url) {
      var s4 = qmSourceOf(this);
      if (s4) {
        try {
          s4.put('qm_used_voice_' + aid + '_' + cid, String(v[k].voice_id || ''))
        } catch (e4) {}
      }
      return String(v[k].voice_url)
    }
  }
  return ''
}

function qmC_JavaOf() {
  try {
    if (this && this.java) return this.java
  } catch (e) {}
  try {
    if (typeof java != 'undefined' && java) return java
  } catch (e2) {}
  return null
}

function qmC_SourceOf() {
  try {
    if (this && this.source) return this.source
  } catch (e) {}
  try {
    if (typeof source != 'undefined' && source) return source
  } catch (e2) {}
  return null
}

function qmC_Map(v, from, to) {
  var out = '';
  v = String(v);
  for (var i = 0; i < v.length; i++) {
    var idx = from.indexOf(v.charAt(i));
    out += idx >= 0 ? to.charAt(idx) : v.charAt(i)
  }
  return out
}

function qmC_ParamEncode(value) {
  var j = qmC_JavaOf.call(this);
  var b64 = String(j.base64Encode(String(value))).replace(/[=\r\n]/g, '');
  return qmC_Map(b64, QM_C_B64, QM_C_PMAP)
}

function qmC_RandomHex(length) {
  var j = qmC_JavaOf.call(this);
  var v = String(j.randomUUID()).replace(/-/g, '');
  while (v.length < length) v += String(j.randomUUID()).replace(/-/g, '');
  return v.slice(0, length)
}

function qmC_Pad(v, len) {
  v = String(v);
  while (v.length < len) v = '0' + v;
  return v
}

function qmC_Day() {
  var d = new Date();
  return d.getFullYear() + qmC_Pad(d.getMonth() + 1, 2) + qmC_Pad(d.getDate(), 2)
}

function qmC_DateStamp() {
  var d = new Date();
  return d.getFullYear() + qmC_Pad(d.getMonth() + 1, 2) + qmC_Pad(d.getDate(), 2) + qmC_Pad(d.getHours(), 2) + qmC_Pad(d.getMinutes(), 2) + qmC_Pad(d.getSeconds(), 2)
}

function qmC_Sign(value) {
  return String(qmC_JavaOf.call(this).md5Encode(String(value) + QM_C_SECRET))
}

function qmC_UrlSign(data) {
  var keys = Object.keys(data || {}).sort();
  var text = '';
  keys.forEach(function(k) {
    text += k + '=' + String(data[k])
  });
  return qmC_Sign.call(this, text)
}

function qmC_Form(data) {
  return Object.keys(data || {}).sort().map(function(k) {
    return encodeURIComponent(k) + '=' + encodeURIComponent(String(data[k]))
  }).join('&')
}

function qmC_Device() {
  var src = qmC_SourceOf.call(this);
  var j = qmC_JavaOf.call(this);
  var d = {};
  try {
    d = JSON.parse(String(src.get('qm_c_device') || '{}'))
  } catch (e) {
    d = {}
  }
  if (!d.uuid) d.uuid = String(j.randomUUID());
  if (!d.device_id) d.device_id = qmC_DateStamp() + qmC_RandomHex.call(this, 48);
  if (!d.source_uid) d.source_uid = qmC_RandomHex.call(this, 16);
  if (!d.mac) d.mac = '02:' + qmC_RandomHex.call(this, 10).match(/../g).join(':');
  d.gender = '0';
  d.static_score = '0.4';
  d.sys_ver = '12';
  d.phone_level = 'M';
  d.app_version = QM_C_APPV;
  d.brand = 'Redmi';
  d.make = 'Redmi';
  d.model = '23117RK66C';
  try {
    src.put('qm_c_device', JSON.stringify(d))
  } catch (e) {}
  return d
}

function qmC_BuildParams(d) {
  var fields = [
    ['gender', d.gender],
    ['static_score', d.static_score],
    ['uuid', d.uuid],
    ['device-id', d.device_id],
    ['mac', d.mac],
    ['sourceuid', d.source_uid],
    ['sys-ver', d.sys_ver],
    ['phone-level', d.phone_level],
    ['app_ver', d.app_version],
    ['imei', ''],
    ['model', d.model],
    ['wlb-imei', ''],
    ['wlb-uid', d.source_uid],
    ['client-id', d.source_uid],
    ['brand', d.brand],
    ['make', d.make],
    ['net_env', '1']
  ];
  var parts = fields.map(function(f) {
    return JSON.stringify(f[0]) + ':' + JSON.stringify(String(f[1]))
  });
  return qmC_ParamEncode.call(this, '{' + parts.join(',') + '}')
}

function qmC_HeaderSign(token, qp) {
  var values = {
    'AUTHORIZATION': token || '',
    'app-version': QM_C_APPV,
    'application-id': QM_C_APPID,
    'channel': QM_C_CHANNEL,
    'is-white': '0',
    'net-env': '1',
    'platform': 'android',
    'qm-params': qp,
    'reg': ''
  };
  var order = ['AUTHORIZATION', 'app-version', 'application-id', 'channel', 'is-white', 'net-env', 'platform', 'qm-params', 'reg'];
  var text = '';
  order.forEach(function(k) {
    text += k + '=' + values[k]
  });
  return qmC_Sign.call(this, text)
}

function qmC_Headers(token) {
  var src = qmC_SourceOf.call(this);
  var d = qmC_Device.call(this);
  var qp = qmC_BuildParams.call(this, d);
  var now = Math.floor(Date.now() / 1000);
  var uid = String(src.get('qm_c_uid') || '');
  return {
    'authorization': token || '',
    'app-version': QM_C_APPV,
    'application-id': QM_C_APPID,
    'channel': QM_C_CHANNEL,
    'is-white': '0',
    'net-env': '1',
    'platform': 'android',
    'qm-params': qp,
    'reg': '',
    'sign': qmC_HeaderSign.call(this, token || '', qp),
    'qm-uaf': qmC_Day() + '-' + uid,
    'qm-it': String(now),
    'qm-ii': String(now % 10000000000),
    'no-permiss': '3',
    'user-agent': 'webviewversion/0',
    'qm-request-id': qmC_Sign.call(this, String(Date.now()) + qmC_RandomHex.call(this, 8))
  }
}

function qmC_Login() {
  var src = qmC_SourceOf.call(this);
  var token = String(src.get('qm_c_token') || '');
  var exp = Number(src.get('qm_c_exp') || 0);
  if (token && exp > Math.floor(Date.now() / 1000) + 60) return token;
  try {
    var form = {
      cancell_check: '1',
      gender: '0'
    };
    form.sign = qmC_UrlSign.call(this, form);
    var headers = qmC_Headers.call(this, '');
    headers['content-type'] = 'application/x-www-form-urlencoded';
    var option = {
      method: 'POST',
      headers: headers,
      body: qmC_Form(form)
    };
    var resp = JSON.parse(String(qmC_JavaOf.call(this).ajax('https://xiaoshuo.wtzw.com/api/v1/login/tourist,' + JSON.stringify(option)) || '{}'));
    token = String((resp && resp.data && resp.data.token) || '');
    if (!token) return '';
    src.put('qm_c_token', token);
    src.put('qm_c_exp', String(Math.floor(Date.now() / 1000) + 3600))
  } catch (e) {
    return ''
  }
  return token
}

function qmC_Request(method, url, params, form) {
  var j = qmC_JavaOf.call(this);
  var token = qmC_Login.call(this);
  var option = {
    method: method,
    headers: qmC_Headers.call(this, token)
  };
  if (form) {
    var body = {};
    Object.keys(form || {}).forEach(function(k) {
      body[k] = String(form[k])
    });
    body.sign = qmC_UrlSign.call(this, body);
    option.headers['content-type'] = 'application/x-www-form-urlencoded';
    option.body = qmC_Form(body)
  } else {
    var query = {};
    Object.keys(params || {}).forEach(function(k) {
      query[k] = String(params[k])
    });
    var parts = Object.keys(query).sort().map(function(k) {
      return encodeURIComponent(k) + '=' + encodeURIComponent(query[k])
    });
    parts.push('sign=' + qmC_UrlSign.call(this, query));
    url += '?' + parts.join('&')
  }
  return JSON.parse(String(j.ajax(url + ',' + JSON.stringify(option)) || '{}'))
}

function qmC_Get(url, params) {
  return qmC_Request.call(this, 'GET', url, params, null)
}

function qmC_PostForm(url, form) {
  return qmC_Request.call(this, 'POST', url, {}, form)
}

function qmC_Esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

