    java.toast("源变量已清除");
 }

function began() {
    var baseVariable = JSON.stringify({
        "sz": "0",
        "tone": "",
        "st": 1,
        "server": API_BASE,
        "type": "小说模式",
        "module": 3,
        "小说路径": "content",
        "漫画路径": "content",
        "短篇路径": "content",
        "漫剧路径": "content",
        "cp": 1,
        "bk": 1,
        "dp": 1
    });
    source.setVariable(baseVariable);
    java.toast("已初始化源变量！");
}

function out(){ java.toast("当前服务器为:\n"+getServerHost()); }

if (source.getVariable()=="") {
    reg(true);
}

var lists = JSON.parse(source.getVariable() || "{}");

function settype(Type) {
    lists.type = Type;
    if (Type == '小说模式') {
        lists.module = "3";
        lists.sz = "0";
        lists.tone = "";
    } else if (Type == '听书模式') {
        lists.module = "2";
        lists.tone = "";
    } else if (Type == '漫画模式') {
        lists.module = "8";
        lists.sz = "0";
        lists.tone = "";
    } else if (Type == '短剧模式') {
        lists.module = "11";
        lists.sz = "0";
        lists.tone = "";
    } else if (Type == '漫剧模式') {
        lists.module = "19";
        lists.sz = "0";
        lists.tone = "";
    } else if (Type == '短篇模式') {
        lists.module = "13";
        lists.sz = "0";
        lists.tone = "";
    }
    source.setVariable(JSON.stringify(lists));
    java.toast('已将类型切换为:\n' + Type);
}
function yu(){
try { u = JSON.parse(source.getVariable() || "{}").type; } catch(e) { u = "小说模式"; }
java.toast('\n'+u)
}

// 登录及登录检查
function login_(openBrowser, checkMode) {
    var cookie_ = String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : source.getLoginInfoMap()['手动登录Token']
    if (cookie_ && cookie_ != "" && !checkMode) {
        java.toast("请不要重复登录，请先退出登录！")
        return false
    }
    if (openBrowser) {
        try { java.startBrowserAwait("https://fanqienovel.com/", "登录") } catch (e) {}
    }
    try { cookie.removeCookie("snssdk.com") } catch (e) {}
    var cookie_ = "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : source.getLoginInfoMap()['手动登录Token'])
    var user
    try {
        user = JSON.parse(java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({method: "GET", headers: {Cookie: cookie_}}))).data.name
    } catch (e) {}
    if (!cookie_ || cookie_ == "sessionid=" || !user) {
        java.toast("未获取到登录凭据，登录失败")
        return false
    }
    java.toast("欢迎 " + user + "\n登录成功！")
    return true
}

function l2(a, b) { try { login_(a, b) } catch (e) {} }
function login() { java.toast("请使用登录界面中的按钮操作"); }
function logout() {
    cookie.removeCookie("fanqienovel.com");
    cookie.removeCookie("snssdk.com");
    if (source.getLoginInfoMap()['手动登录Token']) java.toast("请手动移除填写的Token")
    else java.toast("退出登录成功");
}

// 音色设置
var toneMap={0:"真人",1:"甜美少女",2:"清亮青叔",4:"成熟大叔",5:"开朗青年",6:"温柔淑女",8:"风雅青叔",12:"清纯少女",17:"磁性青叔",27:"推文女声",28:"亲切姐姐",29:"儒雅大叔",30:"优雅御姐",31:"斯文青叔",32:"知性主播",51:"多人对话",74:"成熟升级",90:"多人配乐",100:"俏皮御姐",103:"双音灵动",105:"王明军音",110:"双角对话",115:"从容淑女"};
var modeNames = {
    2: "听书模式",
    3: "小说模式",
    8: "漫画模式",
    11: "短剧模式",
    13: "短篇模式",
    19: "漫剧模式"
};

function set(num) {
    var v = {};
    try { v = JSON.parse(source.getVariable() || "{}"); } catch (e) { v = {}; }
    if (num === 0) {
        v.sz = "0"; v.tone = ""; v.module = 3;
        java.longToast("设置成功\n当前模式：小说模式\n✨纯享阅读✨\n‼️设置完成请点击切换模式‼️");
    } else if (num === 1) {
        v.sz = "1";
        var tid = "";
        try { tid = String(source.getLoginInfoMap()['其他音色ID(确定后✔返回点击切换)'] || '').trim(); } catch(e) {}
        v.tone = tid ? ("tone_id=" + tid) : "";
        v.module = 3;
        java.longToast("设置成功\n当前模式：小说模式\n自定义音色" + (tid ? "(" + tid + ")" : "") + "\n‼️设置完成请点击切换模式‼️");
    } else {
        java.longToast("无效的接口编号！");
        return;
    }
    source.setVariable(JSON.stringify(v));
}

function get() {
    var v = {};
    try { v = JSON.parse(source.getVariable() || "{}"); } catch (e) { v = {}; }
    var currentMode = v.module || 3;
    var sz = parseInt(v.sz || "0", 10);
    var toneName = sz === 0 ? "默认" : (toneMap[String(sz)] || ("音频" + sz));
    var message = "\n当前模式：" + (modeNames[currentMode] || "未知模式");
    if (currentMode === 3 || currentMode === 2) { message += toneName === "默认" ? "\n✨纯享阅读✨" : "\n音色设置：" + toneName; }
    java.longToast(message);
}

function setTone(toneId) {
    var v = {};
    try { v = JSON.parse(source.getVariable() || "{}"); } catch (e) { v = {}; }
    v.sz = String(toneId);
    v.tone = "tone_id=" + toneId;
    v.module = toneId === 0 ? 2 : 3;
    source.setVariable(JSON.stringify(v));
    var name = toneMap[String(toneId)] || ("音频" + toneId);
    java.longToast("设置成功\n当前模式：" + (modeNames[v.module] || "未知模式") + "\n音色设置：" + name + "\n‼️设置完成请点击切换模式‼️");
}

function st() {
    var v = {}; try { v = JSON.parse(source.getVariable() || "{}"); } catch(e) { v = {}; }
    var mode = v.module || 3;
    var newMode;
    if (mode === 3) { newMode = 2; }
    else if (mode === 2) { newMode = 8; }
    else if (mode === 8) { newMode = 11; }
    else if (mode === 11) { newMode = 19; }
    else if (mode === 19) { newMode = 13; }
    else if (mode === 13) { newMode = 3; }
    v.module = newMode;
    v.sz = "0";
    v.tone = "";
    source.setVariable(JSON.stringify(v));
    var msg = "设置成功\n当前模式：" + (modeNames[newMode] || "未知模式") + "\n请前往详情页刷新是否切换成功";
    java.longToast(msg);
}

function reg(is) {
    if (is) {
        try {
            var setData = {
                "search": "-1", "tone_id": "-1", "sz": "0",
                "server": API_BASE, "tone": "", "st": 0,
                "type": "小说模式", "module": "3", "faxian": "小说",
                "小说路径": "content", "漫画路径": "content", "短篇路径": "content", "漫剧路径": "content",
                "cp": 1, "bk": 1, "dp": 1
            };
            source.setVariable(JSON.stringify(setData));
        } catch (e) {}
    }
}

// ===== 段评/章评/书评开关 =====
function toggledp() {
    var v = {};
    try { v = JSON.parse(source.getVariable() || "{}"); } catch (e) { v = {}; }
    setdp((v.dp == 1) ? 0 : 1);
}
function togglecp() {
    var v = {};
