function sortUrlParams(url) {
    var qs = url.split("?")[1];
    if (!qs) return "";
    var params = qs.split("&");
    params.sort(function(a, b) {
        return a.split("=")[0].toLowerCase().localeCompare(b.split("=")[0].toLowerCase());
    });
    var arr = [];
    for (var i = 0; i < params.length; i++) {
        arr.push(params[i].split("=")[1] || "");
    }
    return arr.join("");
}

