    p.jti = java.md5Encode(aesEncode("cd2yj5352pu927mrsn5kmut0saloniy", aeskey, ctx) + ":" + aesEncode(p.iss, aeskey, ctx) + ":" + aesEncode(String(timestamp), aeskey, ctx).toLowerCase());
    var mds = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9." + java.base64Encode(JSON.stringify(p));
    var hmac = java.HMacHex(mds, "HmacSHA256", "1a8154132fg4a784fad101661z1854181ac1qed7");
    hmac = Packages.java.util.Base64.getEncoder().encodeToString(java.hexDecodeToByteArray(hmac));
    return java.base64Encode(mds + "." + toUrlSafeBase64(hmac));
}

function b(n, size) {
    var a = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    var sb = [];
    while (n > 61) {
        sb.push(a.charAt(n % 62));
        n = Math.floor(n / 62);
    }
    sb.push(a.charAt(n));
    return sb.reverse().join("").padStart(size, "0");
}

function aesEncode(str, key, _) {
    return (_ || this).java.createSymmetricCrypto("AES/ECB/PKCS5Padding", key).encryptBase64(str);
}

function toUrlSafeBase64(s) {
    return String(s).replace(/\+/g, "-").replace(/\//g, "_");
}

