var FQ_PROXY_HOST = 'http://121.40.153.11';

function fqSource(javaContext) {
  try { if (typeof source !== 'undefined' && source) return source; } catch (e1) {}
  try { if (javaContext && javaContext.getSource) return javaContext.getSource(); } catch (e2) {}
  try { if (this && this.source) return this.source; } catch (e3) {}
  return null;
}

function fqToken(javaContext) {
  var bookSource = fqSource(javaContext);
  if (!bookSource) return '';
  try {
    var config = JSON.parse(bookSource.getVariable() || '{}');
    var value = config.proxyToken;
    if (value !== undefined && value !== null && String(value).trim()) return String(value).trim();
  } catch (e1) {}
  try {
    var fallback = bookSource.getLoginInfoMap()['请输入token'];
    return fallback === undefined || fallback === null ? '' : String(fallback).trim();
  } catch (e2) { return ''; }
}

function fqSearchUrl(javaContext, keyword, page) {
  return FQ_PROXY_HOST + '/v1/search?key=' + encodeURIComponent(String(keyword || '')) +
    '&page=' + encodeURIComponent(String(page || 1)) + '&token=' + encodeURIComponent(fqToken(javaContext));
}

