@js:(function() {
function extractItemId(value) {
    var text = String(value || "");
    var match = text.match(/[?&]item_id=([^&#]+)/i);
    if (match && match[1]) {
        try { return decodeURIComponent(match[1]); } catch (e) { return match[1]; }
    }
    match = text.match(/item_id[^0-9]*([0-9]{6,})/i);
    return match && match[1] ? match[1] : "";
}

function isHttpUrl(value) {
    var text = String(value || "");
    return text.indexOf("http://") === 0 || text.indexOf("https://") === 0;
}

function decodeVideoUrl(value) {
    var text = String(value || "");
    var decoded;
    var bytes;
    if (text === "") return "";
    if (isHttpUrl(text)) return text;
    try {
        decoded = String(java.base64Decode(text, "UTF-8"));
        if (isHttpUrl(decoded)) return decoded;
    } catch (e) {}
    return text;
}

function getVideoUrl(item) {
    var url = decodeVideoUrl(item && item.main_url);
    if (isHttpUrl(url)) return url;
    url = decodeVideoUrl(item && item.backup_url_1);
    return isHttpUrl(url) ? url : "";
}

function getBestVideoUrl(videoModel) {
    var list = videoModel && videoModel.video_list;
    var candidates = [];
    var key;
    var item;
    var i;
    if (!list) return "";
    for (key in list) {
        if (!list.hasOwnProperty(key)) continue;
        item = list[key];
        if (item && getVideoUrl(item)) candidates.push(item);
    }
    candidates.sort(function(a, b) {
        var ah = Number(a.vheight) || 0;
        var bh = Number(b.vheight) || 0;
        var aw = Number(a.vwidth) || 0;
        var bw = Number(b.vwidth) || 0;
        var ar = Number(a.real_bitrate || a.bitrate) || 0;
        var br = Number(b.real_bitrate || b.bitrate) || 0;
        if (bh !== ah) return bh - ah;
        if (bw !== aw) return bw - aw;
        return br - ar;
    });
    for (i = 0; i < candidates.length; i++) {
        item = candidates[i];
        if (getVideoUrl(item)) return getVideoUrl(item);
    }
    return "";
}

var currentUrl = "";
if (typeof chapter !== "undefined" && chapter && chapter.url) currentUrl = String(chapter.url);
if (!currentUrl && typeof baseUrl !== "undefined" && baseUrl) currentUrl = String(baseUrl);
var itemId = extractItemId(currentUrl);
if (!itemId && typeof baseUrl !== "undefined" && baseUrl) itemId = extractItemId(baseUrl);
if (!itemId) { result = "未找到章节视频ID"; return result; }

var videoUrl;
try {
    videoUrl = geturl(itemId, java);
} catch (e2) {
    result = "播放接口请求失败：" + String(e2.message || e2);
    return result;
}
if (!videoUrl) {
    result = "未找到可播放的视频地址";
    return result;
}

