(function() {
    var list = [];
    var baseUrl = "https://weixin.aikeu.com/ecmsapi/index.php?act=list&mod=movie&page={{page}}&pagesize=10&firsttitle=9";

    var categories = [
        { id: 0, name: "全部" },
        { id: 28, name: "有声小说" },
        { id: 29, name: "广播剧" },
        { id: 30, name: "评书" },
        { id: 31, name: "百家讲坛" },
        { id: 59, name: "粤语" },
        { id: 66, name: "车载专区" },
        { id: 100, name: "儿童" }
    ];

    var sorts = [
        { key: "", label: "推荐" },
        { key: "diggtop desc", label: "网友推荐" },
        { key: "onclick desc", label: "热播" },
        { key: "plnum desc", label: "热评" }
    ];

    function addItem(title, url) {
        list.push({
            title: title,
            url: url,
            style: { layout_flexGrow: 1, layout_flexBasisPercent: 0.25 }
        });
    }

    function addTitle(title) {
        list.push({
            title: title,
            url: null,
            style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 }
        });
    }

    sorts.forEach(function(sort) {
        addTitle("🔥 " + sort.label + " 🔥");
        categories.forEach(function(cat) {
            var url = baseUrl + "&classid=" + cat.id + "&sort=" + encodeURIComponent(sort.key);
            addItem(cat.name, url);
