function sqDate(value) {
    var timestamp = Number(value || 0);
    if (!timestamp) return '';
    if (timestamp < 1000000000000) timestamp *= 1000;
    var date = new Date(timestamp), now = new Date(), diff = now.getTime() - date.getTime();
    if (isNaN(date.getTime())) return '';
    if (diff >= 0 && diff < 60000) return '刚刚';
    if (diff >= 0 && diff < 3600000) return Math.max(1, Math.floor(diff / 60000)) + '分钟前';
    if (diff >= 0 && diff < 86400000) return Math.max(1, Math.floor(diff / 3600000)) + '小时前';
    function pad(number) { return Number(number) < 10 ? '0' + Number(number) : String(number); }
    if (date.getFullYear() == now.getFullYear()) return pad(date.getMonth() + 1) + '-' + pad(date.getDate())
        + ' ' + pad(date.getHours()) + ':' + pad(date.getMinutes());
    return date.getFullYear() + '-' + pad(date.getMonth() + 1) + '-' + pad(date.getDate());
}

