function sqParagraphFallback(ctx, bookId, chapterId) {
    var c = sqContext(ctx), rows = [], grouped = {}, order = [];
    try { rows = sqRows(sqCommentPage(ctx, 'chapter', bookId, chapterId, '', '', 0, 50)); } catch (e) { return []; }
    try { if (c.cache) c.cache.putMemory('sq_comments_all_' + bookId + '_' + chapterId, JSON.stringify(rows)); } catch (ignored) {}
    for (var i = 0; i < rows.length; i++) {
        var item = rows[i] || {}, paragraphId = String(item.paragraphId || '');
        if (!paragraphId || Number(item.targetType || 0) != 8) continue;
        if (!grouped[paragraphId]) {
            grouped[paragraphId] = {
                paragraphId: paragraphId,
                commentCount: 0,
                summaryText: sqCleanText(item.summaryText || ''),
                paragraphOffset: Number(item.paragraphOffset || item.startOffset || -1),
                fallback: 1
            };
