        }
        grouped[paragraphId].commentCount++;
        if (!grouped[paragraphId].summaryText) grouped[paragraphId].summaryText = sqCleanText(item.summaryText || '');
    }
    var result = [];
    for (i = 0; i < order.length; i++) result.push(grouped[order[i]]);
