function sqEmojiHtml(value) {
    var text = String(value == null ? '' : value), pattern = /\[([A-Za-z0-9]+)\]/g, out = '', last = 0, match;
    while ((match = pattern.exec(text)) !== null) {
        out += sqEscape(text.substring(last, match.index));
        var key = String(match[1]), index = SQ_EMOJI_SPRITE.index[key];
        if (index === undefined) index = SQ_EMOJI_SPRITE.index[key.toLowerCase()];
        var column = Number(index) % SQ_EMOJI_SPRITE.columns, row = Math.floor(Number(index) / SQ_EMOJI_SPRITE.columns);
        out += index === undefined ? sqEscape(match[0]) : '<i class="emoji" role="img" aria-label="' + sqEscape(match[0])
            + '" style="background-position:' + (-column * 1.45) + 'em ' + (-row * 1.45) + 'em"></i>';
        last = pattern.lastIndex;
    }
    return out + sqEscape(text.substring(last));
}

