function sqCommentItemHtml(item, replies, isReply, floor, originalIndex) {
    var badges = sqBadges(item), meme = sqMemeUrl(item), text = sqCommentText(item), avatar = String(item.userPhoto || '');
    var likes = sqLikeCount(item), replyCount = sqReplyCount(item), timestamp = Number(item.pubTime || item.createTime || 0);
    var attrs = isReply ? '' : ' data-index="' + Number(originalIndex || 0) + '" data-likes="' + likes + '" data-replies="' + replyCount + '" data-time="' + timestamp + '"';
    var html = '<article class="' + (isReply ? 'reply' : 'item') + (Number(item.isAuthor || 0) == 1 ? ' author' : '') + '"' + attrs + '>';
    if (avatar) html += '<img class="avatar" src="' + sqEscape(avatar) + '">';
    html += '<div class="who">' + sqEscape(item.nickname || '书友');
    for (var b = 0; b < badges.length; b++) html += '<span class="badge">' + sqEscape(badges[b]) + '</span>';
    html += '</div>';
    if (text) html += '<div class="text">' + sqEmojiHtml(text) + '</div>';
    if (meme) html += '<img class="media" src="' + sqEscape(meme) + '">';
    html += '<div class="meta">' + (!isReply && floor ? Number(floor) + '楼 · ' : '') + sqEscape(sqDate(item.pubTime || item.createTime));
    if (item.authorStatusDesc) html += ' · ' + sqEscape(item.authorStatusDesc);
    html += isReply ? '</div>' : ' · 回复</div><div class="like"><b>♡</b>' + likes + '</div>';
    if (!isReply && replies && replies.length) {
        var toggleLabel = '查看' + replyCount + '条回复';
        html += '<button type="button" class="reply-toggle" data-label="' + toggleLabel + '" onclick="sqToggleReplies(this)">' + toggleLabel + '</button><div class="replies">';
        for (var j = 0; j < replies.length; j++) html += sqCommentItemHtml(replies[j] || {}, [], true, 0, j);
        if (replyCount > replies.length) html += '<div class="more">查看更多 ' + (replyCount - replies.length) + ' 条回复</div>';
        html += '</div>';
    }
    return html + '</article>';
}

