function sqShowComments(ctx, bookId, chapterId, paragraphId, total, mode) {
    var c = sqContext(ctx), kind = mode == 'book' ? 'book' : 'chapter';
    var key = 'sq_comments_' + kind + '_' + bookId + '_' + chapterId + '_' + paragraphId + '_' + mode;
    var rows = [], cached = '';
    try { cached = c.cache && c.cache.getFromMemory(key); } catch (ignored) {}
    if (cached) rows = sqParse(cached);
    if (!rows || !rows.length) {
        var size = Math.round(sqClamp(sqStored(ctx, 'shuqi_first_page', '20'), 10, 30, 20));
        try {
            if (mode == 'segment' && String(paragraphId || '').indexOf('|') >= 0) {
                var paragraphIds = String(paragraphId).split('|'), merged = [], seen = {};
                for (var p = 0; p < paragraphIds.length; p++) {
                    if (!paragraphIds[p]) continue;
                    var part = sqRows(sqCommentPage(ctx, kind, String(bookId), String(chapterId), paragraphIds[p], '', 0, size));
                    for (var r = 0; r < part.length; r++) {
                        var identity = String(part[r].mid || (paragraphIds[p] + '_' + r));
                        if (!seen[identity]) { seen[identity] = true; merged.push(part[r]); }
                    }
                }
                rows = merged;
            } else {
                rows = sqRows(sqCommentPage(ctx, kind, String(bookId), String(chapterId),
                    mode == 'chapter' || mode == 'author' ? '' : String(paragraphId), '', 0, size));
            }
            if (mode == 'chapter') rows = rows.filter(function (item) { return Number(item.targetType || 0) == 1; });
            if (mode == 'author') rows = rows.filter(function (item) { return Number(item.isAuthor || 0) == 1; });
            for (var i = 0; i < rows.length; i++) {
                var preview = rows[i].replies && rows[i].replies.commentList || [];
                rows[i]._sqReplies = preview;
            }
            try { if (c.cache) c.cache.putMemory(key, JSON.stringify(rows)); } catch (ignored2) {}
        } catch (e) { c.java.longToast('评论读取失败：' + e); return false; }
    }
    var title = mode == 'book' ? '书评' : (mode == 'chapter' ? '本章说' : (mode == 'author' ? '作者说' : '段评'));
    return sqOpenHtml(ctx, sqCommentHtml(ctx, title, rows, total),
        'shuqi-' + mode + '-' + chapterId + '-' + paragraphId);
}

function sqSvgUrl(ctx, svg, style, action) {
