function sqBubble(ctx, count, bookId, chapterId, paragraphId, mode) {
    var shown = Math.min(999, Number(count || 0));
    if (shown <= 0) return '';
    var size = sqClamp(sqStored(ctx, 'shuqi_bubble_size', '1'), 0.65, 1.6, 1);
    var color = sqStored(ctx, 'shuqi_accent', '#E5353F');
    if (!/^#[0-9a-f]{6}$/i.test(color)) color = '#E5353F';
    var fontSize = shown > 99 ? 68 : (shown > 9 ? 84 : 100);
    var svg = SQ_BUBBLE_SVG.replace(/#E5353F/gi, color)
        .replace('font-size="100"', 'font-size="' + fontSize + '"')
        .replace('>12</text>', '>' + shown + '</text>')
        .replace("viewBox='0 0 216 200'", "width='" + Math.round(31 * size) + "' height='" + Math.round(29 * size) + "' viewBox='0 0 216 200'");
    var action = 'sqShowComments(this,' + Number(bookId) + ',' + Number(chapterId) + ',' + JSON.stringify(String(paragraphId || ''))
        + ',' + shown + ',' + JSON.stringify(mode || 'segment') + ')';
    return '<img src="' + sqSvgUrl(ctx, svg, 'TEXT', action) + '">';
