function sqWrap(value, width, maxLines) {
    var text = sqCleanText(value), lines = [], current = '';
    for (var i = 0; i < text.length; i++) {
        var ch = text.charAt(i);
        if (ch == '\n') { if (current) lines.push(current); current = ''; continue; }
        current += ch;
        if (current.length >= width) { lines.push(current); current = ''; }
    }
    if (current) lines.push(current);
    if (maxLines && lines.length > maxLines) { lines = lines.slice(0, maxLines); lines[maxLines - 1] += '…'; }
    return lines;
}

function sqEndCard(ctx, label, rows, total, bookId, chapterId, mode) {
    var lines = [], names = [], likes = [];
    for (var i = 0; i < rows.length && i < 2; i++) {
        names.push(String(rows[i].nickname || '书友'));
        likes.push(sqLikeCount(rows[i]));
        lines.push(sqWrap(sqCommentText(rows[i]), 25, 2));
    }
    var height = 128 + lines.reduce(function (sum, item) { return sum + Math.max(1, item.length) * 44 + 32; }, 0);
    var body = '<rect width="100%" height="100%" rx="28" fill="#F3E7C9" fill-opacity=".58"/>';
    body += '<text x="38" y="62" font-size="36" fill="#6B5934" font-weight="700">' + sqEscape(label) + '</text>';
    body += '<text x="936" y="62" font-size="30" fill="#7D6B46" text-anchor="end">' + Number(total || rows.length) + '条评论 ›</text>';
    var y = 116;
    for (i = 0; i < lines.length; i++) {
        body += '<text x="40" y="' + y + '" font-size="28" fill="#806C44">' + sqEscape(names[i]) + '</text>';
        body += '<text x="935" y="' + y + '" font-size="26" fill="#806C44" text-anchor="end">♡ ' + likes[i] + '</text>';
        y += 44;
        for (var j = 0; j < lines[i].length; j++) { body += '<text x="40" y="' + y + '" font-size="34" fill="#4F432C">' + sqEscape(lines[i][j]) + '</text>'; y += 44; }
        y += 20;
    }
    var svg = '<svg width="1000" height="' + height + '" xmlns="http://www.w3.org/2000/svg">' + body + '</svg>';
    var action = 'sqShowComments(this,' + Number(bookId) + ',' + Number(chapterId) + ',"",' + Number(total || rows.length) + ',' + JSON.stringify(mode) + ')';
    return '<img src="' + sqSvgUrl(ctx, svg, 'FULL', action) + '">';
}

function sqAuthorSuffix(value) {
