    if (!suffix) return '';
    try {
        var json = sqParse(c.java.ajax('https://c13.shuqireader.com/sapi/chapter/authorwords/' + suffix, 8000));
        var words = String(json.state || json.status || '') == '200' ? sqCleanText(json.author_words || json.authorWords || '') : '';
        if (/^[A-Za-z0-9+/=]{80,}$/.test(words.replace(/\s+/g, ''))) return '';
        return words;
    } catch (e) { return ''; }
}

function sqAuthorCard(ctx, author, text) {
    var lines = sqWrap(text, 25, 16), height = 145 + lines.length * 48, body = '';
    if (!lines.length) return '';
    body += '<rect width="100%" height="100%" rx="28" fill="#F1E2BE" fill-opacity=".72"/>';
    body += '<rect x="820" y="0" width="180" height="58" rx="0" fill="#6689E8"/>';
    body += '<text x="910" y="40" text-anchor="middle" font-size="30" fill="#FFF" font-weight="700">作者说</text>';
    body += '<circle cx="74" cy="72" r="28" fill="#D3C398"/><text x="118" y="82" font-size="32" fill="#574A31">' + sqEscape(author || '作者') + '</text>';
    for (var i = 0; i < lines.length; i++) body += '<text x="46" y="' + (138 + i * 48) + '" font-size="34" fill="#5A4C31">' + sqEscape(lines[i]) + '</text>';
    return '<img src="' + sqSvgUrl(ctx, '<svg width="1000" height="' + height + '" xmlns="http://www.w3.org/2000/svg">' + body + '</svg>', 'FULL', '') + '">';
}

function sqChapterExtras(ctx, text, requestUrl, contentHtml) {
    var bookId = sqBookId(requestUrl), chapterId = sqChapterId(requestUrl), c = sqContext(ctx);
    if (!bookId || !chapterId) return text;
    var paragraphs = [], chapterRows = [], authorRows = [];
    if (sqEnabled(ctx, 'shuqi_segments') || sqEnabled(ctx, 'shuqi_chapter_talk') || sqEnabled(ctx, 'shuqi_author_words')) {
        try {
            var ext = sqExt(ctx, bookId, chapterId), info = ext.bookChapterExtInfo || {};
            paragraphs = info.paragraphList || [];
            if (!paragraphs.length && sqEnabled(ctx, 'shuqi_segments')) paragraphs = sqParagraphFallback(ctx, bookId, chapterId);
            try { c.source.put('shuqi_comment_error', ''); } catch (ignored) {}
        } catch (e) { try { c.source.put('shuqi_comment_error', String(e)); } catch (ignored2) {} }
    }
    var rows = sqContentModel(text, contentHtml), bubbles = {}, titleBubble = '', i;
    if (sqEnabled(ctx, 'shuqi_segments')) {
        var bubbleGroups = {};
        for (i = 0; i < paragraphs.length; i++) {
            var p = paragraphs[i] || {}, count = Number(p.commentCount || 0);
            var hasOrder = p.orderId !== undefined && p.orderId !== null && String(p.orderId) !== '';
            var order = hasOrder ? Number(p.orderId) : -1;
            if (count <= 0) continue;
            var summary = sqCleanText(p.summaryText || ''), summaryPosition = -1;
            if (summary) {
                var comparableSummary = sqComparable(summary);
                for (var s = 0; s < rows.length; s++) {
                    var candidate = sqComparable(rows[s].text || '');
                    if (candidate == comparableSummary || candidate.indexOf(comparableSummary) >= 0 || comparableSummary.indexOf(candidate) >= 0) { summaryPosition = s; break; }
                }
            }
            if (summaryPosition >= 0) order = summaryPosition + 1;
            else if (!hasOrder && p.fallback) {
                if (/^\s*(第\s*[0-9零一二三四五六七八九十百千万两]+\s*[章节回卷篇]|楔子|序章|前言|引子|番外)/.test(summary)) order = 0;
                else continue;
            }
            var position = order === 0 ? -1 : order - 1;
            if (position >= rows.length) position = rows.length - 1;
            if (position < -1) continue;
            var groupKey = String(position), paragraphId = String(p.paragraphId || '');
            if (!bubbleGroups[groupKey]) bubbleGroups[groupKey] = { ids: [], counts: {}, total: 0 };
            var group = bubbleGroups[groupKey], idKey = paragraphId || ('__empty_' + i);
            if (!Object.prototype.hasOwnProperty.call(group.counts, idKey)) group.ids.push(paragraphId);
            group.counts[idKey] = Math.max(Number(group.counts[idKey] || 0), count);
        }
        for (var groupPosition in bubbleGroups) if (Object.prototype.hasOwnProperty.call(bubbleGroups, groupPosition)) {
            var bubbleGroup = bubbleGroups[groupPosition], totalCount = 0, usableIds = [];
            for (var id in bubbleGroup.counts) if (Object.prototype.hasOwnProperty.call(bubbleGroup.counts, id)) totalCount += bubbleGroup.counts[id];
            for (var g = 0; g < bubbleGroup.ids.length; g++) if (bubbleGroup.ids[g] && usableIds.indexOf(bubbleGroup.ids[g]) < 0) usableIds.push(bubbleGroup.ids[g]);
            if (!usableIds.length) continue;
            var bubble = sqBubble(ctx, totalCount, bookId, chapterId, usableIds.join('|'), 'segment');
            if (Number(groupPosition) === -1) titleBubble = bubble;
            else bubbles[Number(groupPosition)] = bubble;
        }
    }
    var out = [];
    if (titleBubble) out.push(titleBubble);
    for (i = 0; i < rows.length; i++) {
        var line = rows[i] || {}, imageHtml = line.images && line.images.length ? line.images.join('') : '';
        out.push('<p>' + sqEscape(line.text || '') + (bubbles[i] || '') + imageHtml + '</p>');
    }
    if (sqEnabled(ctx, 'shuqi_chapter_talk') || sqEnabled(ctx, 'shuqi_author_words')) {
        try {
            var allCached = '', all = [];
            try { allCached = c.cache && c.cache.getFromMemory('sq_comments_all_' + bookId + '_' + chapterId); } catch (ignored3) {}
            all = allCached ? sqParse(allCached) : sqRows(sqCommentPage(ctx, 'chapter', bookId, chapterId, '', '', 0, 20));
            for (i = 0; i < all.length; i++) {
                if (Number(all[i].isAuthor || 0) == 1) authorRows.push(all[i]);
                else if (Number(all[i].targetType || 0) == 1) chapterRows.push(all[i]);
            }
            if (c.cache) c.cache.putMemory('sq_comments_chapter_' + bookId + '_' + chapterId + '__chapter', JSON.stringify(chapterRows));
            if (c.cache) c.cache.putMemory('sq_comments_chapter_' + bookId + '_' + chapterId + '__author', JSON.stringify(authorRows));
        } catch (ignored5) {}
    }
    if (sqEnabled(ctx, 'shuqi_author_words')) {
        var words = sqLegacyAuthorWords(ctx, requestUrl), author = '作者';
        try { author = String(book.author || '作者'); } catch (ignored4) {}
        if (words) out.push(sqAuthorCard(ctx, author, words));
        if (authorRows.length) out.push(sqEndCard(ctx, '作者说', authorRows, authorRows.length, bookId, chapterId, 'author'));
    }
    if (sqEnabled(ctx, 'shuqi_chapter_talk') && chapterRows.length) {
        out.push(sqEndCard(ctx, '本章说', chapterRows, chapterRows.length, bookId, chapterId, 'chapter'));
    }
    return out.join('\n');
}

function sqRenderContent(ctx, response, requestUrl) {
    var data = sqParse(response), text = '', contentHtml = '';
    if (data && data.ok === true && (data.contentHtml != null || data.content != null || data.text != null)) {
        text = String(data.content || data.text || '');
        contentHtml = String(data.contentHtml || '');
    } else if (!data || Object.keys(data).length === 0) {
        return '请先在书源登录页配置正文接口和 API Key，然后刷新目录';
    } else {
        var message = String(data.message || data.msg || data.error || '未知错误');
        return /not found/i.test(message) ? ('正文接口未收录本章：' + message) : ('正文接口请求失败：' + message);
    }
    return sqChapterExtras(ctx, text, requestUrl, contentHtml);
}

function sqBookIntro(ctx, intro, baseUrl) {
    var description = sqCleanText(intro), bookId = sqBookId(baseUrl);
    if (!bookId || !sqEnabled(ctx, 'shuqi_reviews')) return description;
    try {
        var data = sqCommentPage(ctx, 'book', bookId, '', '', '', 0, 5), rows = sqRows(data), lines = [];
        for (var i = 0; i < rows.length; i++) {
            var text = sqCommentText(rows[i]);
            if (text) lines.push((rows[i].hotComment ? '★ ' : '') + String(rows[i].nickname || '书友') + '：' + text
                + '（赞 ' + sqLikeCount(rows[i]) + ' · 回复 ' + sqReplyCount(rows[i]) + '）');
        }
        return lines.length ? description + '\n\n【书评】\n' + lines.join('\n') : description;
    } catch (e) { return description; }
}

