function shuqiLoginInfo() {
    try { if (typeof result != 'undefined' && result) return result; } catch (e) {}
    try { return source.getLoginInfoMap(); } catch (e2) { return null; }
}
function shuqiValue(info, key) {
    if (!info) return '';
    try { var value = info.get(key); return value == null ? '' : String(value); } catch (e) {}
    try { return info[key] == null ? '' : String(info[key]); } catch (e2) { return ''; }
}
function login(save) {
    var info = shuqiLoginInfo();
    var api = shuqiValue(info, '正文接口').trim().replace(/\/+$/, '');
    var key = shuqiValue(info, 'API Key').trim();
    if (!api) { java.toast('请填写正文接口'); return false; }
    if (!/^https?:\/\//i.test(api)) { java.toast('正文接口必须以 http:// 或 https:// 开头'); return false; }
    if (!key) { java.toast('请填写 API Key'); return false; }
    source.put('shuqi_oe_api', api);
    source.put('shuqi_oe_key', key);
    try {
        var old = shuqiLoginInfo(), data = {
            '正文接口': api, 'API Key': key,
            '气泡大小': shuqiValue(old, '气泡大小') || '1.0',
            '评论字号': shuqiValue(old, '评论字号') || '16',
