        };
        source.putLoginInfo(JSON.stringify(data));
    } catch (ignored) {}
    java.longToast('正文配置已保存\n' + api);
    return true;
}
function shuqiCheckConfig() {
    var api = String(source.get('shuqi_oe_api') || '').trim();
    var key = String(source.get('shuqi_oe_key') || '').trim();
    java.longToast('正文接口：' + (api ? '已配置' : '未配置') + '\nAPI Key：' + (key ? '已配置' : '未配置'));
    return !!(api && key);
}
function shuqiClearConfig() {
    source.put('shuqi_oe_api', '');
    source.put('shuqi_oe_key', '');
    try { source.putLoginInfo(JSON.stringify({ '正文接口': '', 'API Key': '', '气泡大小': '1.0', '评论字号': '16', '首屏条数': '20', '主题色': '#E5353F' })); } catch (ignored) {}
    java.toast('正文配置已清除');
    return true;
}
function shuqiToggle(key, label) {
    var enabled = String(source.get(key) || '') != 'off';
    source.put(key, enabled ? 'off' : 'on');
    java.toast(label + (enabled ? '已关闭' : '已开启'));
    return true;
}
function shuqiSetComments(enabled) {
    var value = enabled ? 'on' : 'off', keys = ['shuqi_segments','shuqi_chapter_talk','shuqi_author_words','shuqi_reviews'];
    for (var i = 0; i < keys.length; i++) source.put(keys[i], value);
    java.toast('评论与作者说已全部' + (enabled ? '开启' : '关闭') + '，请刷新正文');
    return true;
}
function shuqiSaveStyle() {
    var info = shuqiLoginInfo(), size = Number(shuqiValue(info, '气泡大小') || 1), font = Number(shuqiValue(info, '评论字号') || 16);
    var count = Number(shuqiValue(info, '首屏条数') || 20), color = String(shuqiValue(info, '主题色') || '#E5353F').trim();
    if (!isFinite(size) || size < 0.65 || size > 1.6) { java.toast('气泡大小范围为 0.65 - 1.6'); return false; }
    if (!isFinite(font) || font < 13 || font > 24) { java.toast('评论字号范围为 13 - 24'); return false; }
    if (!isFinite(count) || count < 10 || count > 30) { java.toast('首屏条数范围为 10 - 30'); return false; }
    if (!/^#[0-9a-f]{6}$/i.test(color)) { java.toast('主题色格式应为 #E5353F'); return false; }
    source.put('shuqi_bubble_size', String(size)); source.put('shuqi_comment_font', String(font));
    source.put('shuqi_first_page', String(Math.round(count))); source.put('shuqi_accent', color);
    try {
        source.putLoginInfo(JSON.stringify({ '正文接口': String(source.get('shuqi_oe_api') || ''), 'API Key': String(source.get('shuqi_oe_key') || ''),
            '气泡大小': String(size), '评论字号': String(font), '首屏条数': String(Math.round(count)), '主题色': color }));
    } catch (ignored) {}
    java.toast('评论样式已保存，请刷新正文'); return true;
}
function shuqiCommentStatus() {
    function state(key) { return String(source.get(key) || 'on') == 'off' ? '关闭' : '开启'; }
    var error = String(source.get('shuqi_comment_error') || '');
