// ==================== 全局常量·干净规整 ====================
const MODE_MAP = {
    2: "听书模式",
    3: "小说模式",
    8: "漫画模式",
    11: "短剧模式"
};
const MODE_CODE = {
    "听书模式": 2,
    "小说模式": 3,
    "漫画模式": 8,
    "短剧模式": 11
};

// 音色只存纯净ID，彻底抛弃 tone_id=xxx 弱智拼接
const VOICE_LIST = [
    ["正常模式", ""],
    ["自定义音色", ""],
    ["真人", "0"],
    ["甜美少女", "1"],
    ["清亮青叔", "2"],
    ["成熟大叔", "4"],
    ["开朗青年", "5"],
    ["温柔淑女", "6"],
    ["风雅青叔", "8"],
    ["清纯少女", "12"],
    ["磁性青叔", "17"],
    ["推文女声", "27"],
    ["亲切姐姐", "28"],
    ["儒雅大叔", "29"],
    ["优雅御姐", "30"],
    ["斯文青叔", "31"],
    ["知性主播", "32"],
    ["多人对话", "51"],
    ["成熟升级", "74"],
    ["俏皮御姐", "100"],
    ["双音灵动", "103"],
    ["王明军音", "105"]
];

// ==================== 核心工具·根治所有空JSON报错 ====================
function safeParse(raw) {
    try {
        const txt = (raw || "").trim();
        return txt ? JSON.parse(txt) : {};
    } catch (e) {
        return {};
    }
}
function getConfig() {
    return safeParse(source.getVariable());
}
function saveConfig(cfg) {
    source.setVariable(JSON.stringify(cfg, null, "\t"));
}

// ==================== 独立专用：只清空音色【绝不修改模式】====================
function clearVoiceOnly() {
    const cfg = getConfig();
    // 只清音色相关字段，module模式一丝不动！
    cfg.sz = "0";
    cfg.tone = "";
    cfg.toneId = "";
    saveConfig(cfg);
}

// ==================== 空占位·保留入口 ====================
function login() {}

// ==================== 手动指定模式：锁死正确模式，只清音色 ====================
function settype(Type) {
    const cfg = getConfig();
    cfg.type = Type;
    // 严格锁定对应模式编号：2/3/8/11 绝不乱改
    const targetModule = MODE_CODE[Type] || 3;
    cfg.module = targetModule;
    saveConfig(cfg);

    // 规则：不是听书(2)，就只清空音色，不改模式
    if (targetModule !== 2) {
        clearVoiceOnly();
    }
    java.toast("已切换为：\n" + Type);
}

// ==================== 手动选音色set：原有逻辑完整保留 ====================
function set(num) {
    if (num < 0 || num >= VOICE_LIST.length) {
        java.longToast("无效的接口编号！");
        return;
    }
    const cfg = getConfig();
    const [voiceName, pureToneId] = VOICE_LIST[num];

    // 手动点音色才触发模式切换，和切换模式功能彻底分开
    if (num === 0 || num === 1) {
        cfg.module = 3;
    } else {
        cfg.module = 2;
    }

    cfg.sz = String(num);
    cfg.tone = pureToneId ? ("tone_id=" + pureToneId) : "";
    cfg.toneId = pureToneId;

    saveConfig(cfg);
    const nowMode = MODE_MAP[cfg.module] || "未知模式";
    const msg = `设置成功
当前模式：${nowMode}
音色：${voiceName}
‼️如需生效请刷新切换模式`;
    java.longToast(msg);
}

// ==================== 查看当前配置 ====================
function get() {
    try {
        const cfg = getConfig();
        const nowMode = MODE_MAP[cfg.module] || "未知模式";
        let msg = "\n当前模式：" + nowMode;

        if (cfg.module === 2 || cfg.module === 3) {
            const sz = parseInt(cfg.sz || "0", 10);
            const voiceName = VOICE_LIST[sz] ? VOICE_LIST[sz][0] : "默认";
            msg += "\n当前音色：" + voiceName;
        }
        java.longToast(msg);
    } catch (e) {
        java.longToast("获取配置失败，已自动兜底");
    }
}

// ==================== 循环滚动模式：严格保留2/3/8/11，只清音色 ====================
function st() {
    const cfg = getConfig();
    const now = parseInt(cfg.module) || 3;
    let newMode = 3;

    // 严格循环：3→2→8→11→3 不乱跳
    switch (now) {
        case 3: newMode = 2; break;
        case 2: newMode = 8; break;
        case 8: newMode = 11; break;
        case 11: newMode = 3; break;
    }

    cfg.module = newMode;
    saveConfig(cfg);

    // 非听书模式，只清音色，不改模式
    if (newMode !== 2) {
        clearVoiceOnly();
    }

    const msg = `模式切换成功
当前：${MODE_MAP[newMode]}
请刷新生效`;
    java.longToast(msg);
}

// ==================== 旧兼容接口·保留不删 ====================
function getArgument(key) {
    const cfg = getConfig();
    return cfg[key] ?? "";
}
function setArgument(key, value) {
    const cfg = getConfig();
    cfg[key] = value;
    saveConfig(cfg);
    return cfg;
}
const yu = () => {
    const cfg = getConfig();
    java.toast("\n" + (cfg.type || "未设置"));
};

