loginUrl:
let uuid = 'android' + java.randomUUID()

function getAuthCode(v) {
  let login_name = v || result['手机号码/邮箱']
  let phone_num = ''
  let url = getUrl('/signup/send_verify_code', { verify_type: 5, login_name: login_name, phone_num: phone_num, timestamp: Date.now() })
  decrypt(java.ajax(url), null, true)
}

function login(username, password) {
  if (value('login_token')) {
    throw new Error("重新登录请先清除登录缓存")
  }
  let userInfo = source.getLoginInfoMap() || {}
  let username = userInfo['手机号码/邮箱'] || ''
  let password = userInfo['密码'] || ''
  let ver_code = userInfo['验证码'] || ''
  let isAuto = username == '' || (password == '' && ver_code == ''), loginUrl
  if (isAuto) {
    loginUrl = getUrl('/signup/auto_reg_v2', { oauth_union_id: '', gender: 1, app_version: '2.9.337', oauth_open_id: '', device_token: 'ciweimao_', channel: 'Common', oauth_type: '', uuid: uuid })
  } else if (password != '' || String(username).includes('@')) {
    let test = JSON.parse(decrypt(java.ajax(getUrl('/signup/use_geetest', { login_name: username }))))
    if (test.data.need_use_geetest != 0) {
      getAuthCode(username)
      Packages.java.lang.Thread.sleep(1000)
      let yzm = java.getVerificationCode('data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7')
      loginUrl = getUrl('/signup/login', { login_name: username, passwd: password, to_code: 1, ver_code: yzm })
    } else {
      let data = { login_name: username, passwd: password }
      if (ver_code != '') {
        data.to_code = 1
        data.ver_code = ver_code
      }
      loginUrl = getUrl('/signup/login', data)
    }
  } else {
    loginUrl = getUrl('/signup/login_v2', { channel: 'PCdownloadC', phone_num: '1-' + username, ver_code: ver_code, uuid: uuid })
  }
  // 获取登录信息
  let res = JSON.parse(decrypt(java.ajax(loginUrl))).data
  value('login_token', res.login_token)
  value('user_code', res.user_code)
  let account = value('account', res.reader_info.account)
  let hlb = value('rest_hlb', res.prop_info.rest_hlb)
  java.longToast(isAuto ? '游客登陆成功' : `${account}登录成功\n剩余欢乐币:${hlb}`)
  // 获取书架
  let bookList = java.ajax(getUrl('/bookshelf/get_shelf_list', {}))
  decrypt(bookList, null, true)
  let shelf_list = JSON.parse(decrypt(bookList)).data.shelf_list[0]
  value('shelf_id', shelf_list.shelf_id)
  value('reader_id', shelf_list.reader_id)
  return true
}

function clearLogin() {
  source.variable = ''
  java.longToast('清除成功！')
}

function showDb() {
  var option = {
    "method": "GET",
    "headers": { "x-sec-token": source.get('token') },
    "webView": false
  }
  var res = java.ajax(`${api}/dbinfo,` + JSON.stringify(option))
  data = JSON.parse(res).data
  var tip = `\n书籍数：${data.novel_count}\n总章节数：${data.chapter_count}\n总字数：${data.character_count}\n最近更新时间：${data.last_updated}`
  java.longToast(tip)
}

function saveToken(v) {
  let token = v || result['共享Token']
  if (String(token).length <= 60) {
    java.toast('请输入有效token')
  } else {
    let res = java.ajax(getApiUrl('/token/test', { token: token }, this))
    let data = JSON.parse(res)
    if (data.code == 0) {
      source.put('token', token)
      let info = data.data
      java.longToast(`\n✅查询成功\n${info.msg}`)
      source.putLoginInfo(JSON.stringify(result))
    } else {
      java.longToast('\n❌查询失败\n' + data.error)
    }
  }
}

function buy(num) {
  let shelf_id = value('shelf_id')
  if (!shelf_id) {
    java.toast('请先登录')
    return
  }
  let rest_hlb = value('rest_hlb')
  if (rest_hlb <= 0) {
    java.toast('余额不足，当前余额：' + rest_hlb)
    return
  }
  let bid = String(result['书籍ID'])
  if (bid == '') {
    java.toast('请先输入书籍ID')
    return
  }
  if (num) {
    num = parseInt(result['章节数量']) || 10
    // java.toast(`书籍：${bid} 余额：${rest_hlb} 购买章节数：${num}`)
    let perUrl = getUrl('/chapter/get_chapter_permission_list', { book_id: bid })
    let perRes = JSON.parse(decrypt(java.ajax(perUrl))).data.chapter_permission_list
    let startIndex = perRes.findIndex(item => item.auth_access == 0 && item.unit_hlb != 0)
    let hlb = rest_hlb
    let chaps = []
    for (let i = 0; chaps.length < num; i++) {
      let info = perRes[startIndex + i]
      if (!info) {
        break
      }
      if (info.auth_access == 0 && info.unit_hlb != 0) {
        if (hlb < +info.unit_hlb) {
          break
        }
        chaps.push(info.chapter_id)
        hlb -= info.unit_hlb
      }
    }
    if (chaps.length == 0) {
      java.toast('没有可购买的章节')
      return
    }
    let sussessCount = 0
    for (let chapter_id of chaps) {
      java.toast(`购买章节：${chapter_id}`)
      let payUrl = getUrl('/chapter/buy', { shelf_id: shelf_id, chapter_id: chapter_id })
      let payRes = JSON.parse(decrypt(java.ajax(payUrl)))
      if (payRes.code == '100000') {
        sussessCount++
      } else {
        java.toast(`购买失败：${payRes.tip}`)
      }
      Packages.java.lang.Thread.sleep(2000)
    }
    if (sussessCount > 0) {
      let propUrl = getUrl('/reader/get_prop_info', {})
      let propRes = JSON.parse(decrypt(java.ajax(propUrl)))
      let rest_hlb = propRes.data.prop_info.rest_hlb
      value('rest_hlb', rest_hlb)
      java.toast(`购买成功：共购买${sussessCount}章  余额：${rest_hlb}`)
    } else {
      java.toast('购买失败，请稍后再试')
    }
  } else {
    let priceUrl = getUrl('/book/get_price', { book_id: bid })
    let priceRes = JSON.parse(decrypt(java.ajax(priceUrl)))
    if (priceRes.code != '100000') {
      java.toast(`获取全书价格失败：${priceRes.tip}`)
      return
    }
    let price = +priceRes.data.buy_info.price
    if (rest_hlb < price) {
      java.toast(`余额不足，当前余额：${rest_hlb} 全书价格：${price}`)
      return
    }
    let buyUrl = getUrl('/book/buy', { book_id: bid, shelf_id: shelf_id })
    let buyRes = JSON.parse(decrypt(java.ajax(buyUrl)))
    if (buyRes.code == '100000') {
      java.toast('购买成功')
      let propUrl = getUrl('/reader/get_prop_info', {})
      let propRes = JSON.parse(decrypt(java.ajax(propUrl)))
      let rest_hlb = propRes.data.prop_info.rest_hlb
      value('rest_hlb', rest_hlb)
    } else {
      java.toast(`购买失败：${buyRes.tip}`)
    }
  }
  source.putLoginInfo(JSON.stringify(result))
}

function switchSetting(key, name) {
  if (key == 'tsukkomi' && !java.startBrowserAwait.toString().includes(',boolean')) {
