    paragraph[v.paragraph_index] += ` <img src="//-${v.tsukkomi_num}-${v.chapter_id}-${v.paragraph_index},{\"click\":\"tsukkomi(result)\",\"js\":\"tsukkomi(result)\"}">`
  }
  body = paragraph.join('\n')
  source.put(cid, '1')
  if (!cvalue(cid)) { cvalue(cid, 0) } else cvalue(cid, Date.now())
}
if (uc == 1) {
  let date = new Date().toLocaleDateString()
  if (value('last_read') != date) {
    java.ajax(getUrl('/reader/add_readbook', { readTimes: parseInt(Math.random() * (1000 - 600)) + 600, getTime: encodeURI(new Date().toISOString().replace('T', ' ').slice(0, 19)), book_id: java.get('bid') }))
    value('last_read', date)
    java.toast('今日阅读完成！')
  }
  body = java.ajax(getUrl('/chapter/get_cpt_ifm', { chapter_command: result, chapter_id: cid }))
  let data = JSON.parse(decrypt(body)).data
  let de = ''
  if (/🐱$/.test(chapter.tag)) {
    let url = getApiUrl('/chaps', { novelId: java.get('bid'), chapId: cid })
    let res = JSON.parse(java.ajax(url))
    de = res.data.content
  } else if (data && data.chapter_info && data.chapter_info.txt_content) {
    de = decrypt(data.chapter_info.txt_content, result)
  }
  if (!data || !data.chapter_info) {
    body = de || '章节内容加载失败，可能为下载章节，请稍后再试！'
  } else {
    let chInfo = data.chapter_info
    let s = s => String(s).trim().split('\n')
    let content = s(removeRareChineseChars(de))
    let isPay = chInfo.is_paid == 1 && chInfo.auth_access == 0
    let payText = `\n——————————\n未购章节，购买后才能阅读\n价格：${chInfo.unit_hlb}，余额：${rest_hlb}\n点击右上角购买，购买后自动加入到个人书架\n购买后需刷新页面\n——————————`
    if (!/🐱$/.test(chapter.tag) && isPay) {
      content = content.concat(s(payText))
    }
    if (chInfo.author_say && source.get('noAuthorSay') != '1') {
      content = content.concat(s(chInfo.author_say))
    }
    if (java.startBrowserAwait.toString().includes(',boolean') && source.get('tsukkomi') == '1') {
      content.unshift(chapter.title)
      getTsk(content)
    } else {
      body = content.join('\n')
    }
    try {
      if (!/🐱$/.test(chapter.tag)) {
        if (/(🔑|✰)$/.test(chapter.tag) || (chInfo.is_paid == 1 && chInfo.auth_access == 1)) {
          chInfo.txt_content = String(de)
          var option = {
            "method": "POST",
            "body": chInfo,
            "headers": { "x-sec-token": source.get('token') }
          }
          java.ajax(`${api}/upload,` + JSON.stringify(option))
        }
      }
    } catch { }
  }
} else if (uc == 2) {
  body = java.ajax(getUrl('/chapter/get_comic_chapter', { chapter_command: result, chapter_id: cid, img_index: 1 }))
  let info = JSON.parse(decrypt(body)).data.chapter_info
  let imgs = info.images
  let img = info.img
  body = ''
  if (img) {
    body = '<img src="data:image/webp;base64,' + decrypt(img, result) + '">'
    let isPay = info.is_paid && info.auth_access == 0
    let payText = `\n——————————\n未购章节，购买后才能阅读\n价格：${info.unit_hlb}，余额：${rest_hlb}\n点击右上角购买，购买后自动加入到个人书架\n——————————`
    body = isPay ? body + payText : body
  } else {
    for (i in imgs) {
      body += '<img src="' + info.image_path + i + '">\n'
    }
  }
  body
} else if (uc == 4) {
  body = java.ajax(getUrl('/chapter/get_cpt_dub_audio', { audio_command: result, chapter_id: cid, voice: 40 }))
  let data = JSON.parse(decrypt(body)).data
  body = data.cpt_m + '&account=' + value('account') + '&device_token=' + value('device_token') + '&chapter_id=' + cid
}
