ruleToc.chapterList:
@js:
let uc = java.get('type')
//java.log('目录url：' + book.tocUrl)
let bid = book.tocUrl.match(/book_id.*?(\d+)/)[1]
let token = String(source.get('token')).trim()
result = JSON.parse(result).data
if (token && !result) {
  result = java.get(`${api}/volumelist?novelId=${bid}`, { "x-sec-token": token }).body()
  result = JSON.parse(result).data || []
} else {
  result = result.chapter_list
}
//java.log(JSON.stringify(result, null, 2))
java.put('bid', bid)

var resp = ''
if (token && uc == 1) {
  try {
    resp = java.get(`${api}/dirs?novelId=${bid}`, { "x-sec-token": token }).body()
  } catch { }
}
cacheDir = []
try {
  cacheDir = JSON.parse(resp || "{}").data || []
} catch { }
let dirsData = cacheDir.reduce((acc, cur) => {
  acc[cur.chapter_id] = cur
  return acc
}, {})

let chList = []
result.forEach(volList => {
  chList.push({ title: volList.division_name, voltype: true })
  volList.chapter_list.forEach(item => {
    let url = '/chapter/get_chapter_cmd'
    if (uc == 2) {
      url = '/chapter/get_comic_chapter_cmd'
      book.type = 64
    } else if (uc == 4) {
      url = '/chapter/get_chapter_audio_cmd'
      book.type = 32
    }
    url = `@js:getUrl("${url}", { chapter_id: "${item.chapter_id}" })`
    //java.log(url)
    let dirsChapInfo = dirsData[item.chapter_id]
    let isShare = !!dirsChapInfo
    if (isShare && item.chapter_title == '该章节未审核通过') {
      item.chapter_title = dirsChapInfo.chapter_title
      item.is_paid = dirsChapInfo.is_paid
    }
    let isVip = item.is_paid == 1
    let isPay = isVip && item.auth_access == 1
    let tag = ''
    if (isVip) {
      if (isPay && !isShare) {
        tag = '🔑'
      } else if (isShare) {
        tag = '🐱'
      }
    } else {
      if (!isShare) {
        tag = '✰'
      } else {
        tag = '🐱'
      }
    }
    //java.log(`${item.chapter_id} isShare: ${isShare}, isVip: ${isVip}, isPay: ${isPay}, tag: ${tag}`)
    data = {
      cid: item.chapter_id,
      title: (isPay ? '🔑' : (isVip && isShare ? '🐱' : '')) + item.chapter_title,
      isVip: isVip && !isShare && !isPay,
      isPay: isPay,
      url: url,
      info: `更新时间 ${item.mtime} 字数 ${item.word_count} ${tag}`
    }
    chList.push(data)
  })
})
