@js:
var text = String(title || result || "");
var cid = "";
var bid = "";

try {
    var base64 = baseUrl.match(/data:;base64,([^,]+)/)[1];
    cid = java.base64Decode(base64);
    var urlObj = JSON.parse(baseUrl.slice(baseUrl.indexOf("{")));
    bid = urlObj.novelId || "";
} catch(e) {
    cid = "";
    bid = "";
}

var bubble = "";
var cfg;
try { cfg = getCfg.call(this); } catch(eC) { cfg = { zm: false }; }

// imgUrl is persisted in the chapter database; clear it before recalculating the title bubble.
try { chapter.putImgUrl(null); } catch(eClearTitleImage) {}

if (cfg.zm && cid && bid) {
    try {
        var count = 0;
        var hot = false;
        var summaryRes = qdGetParagraphSummary.call(this, bid, cid);
        var sd = summaryRes.data || summaryRes.Data || {};
        var summary = qdList(sd.summary || sd.Summary);
        for (var i = 0; i < summary.length; i++) {
            var item = summary[i] || {};
            var pid = Number(
                item.ParagraphId || item.paragraphId || item.paragraph_id ||
                item.ParaId || item.paraId || 0
            );
            if (pid === -1) {
                count = Number(
                    item.CommentCount || item.commentCount || item.TextCount ||
                    item.textCount || item.Count || item.count || 0
                );
                hot = Number(item.HasHotComment || item.hasHotComment || 0) !== 0;
                break;
            }
        }
        if (count > 0) bubble = createSvg.call(this, count, bid, cid, -1, hot, true, "dp");
    } catch(e) {
        bubble = "";
    }
}
text + bubble;

